function freshState(seed=Date.now()){const next=createState('',seed,{locale:'ko'});next.creationSeed=seed>>>0;next.name=generateKoreanName(next.creationSeed,next.gender);return next;}
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(ko,en)=>lang==='ko'?ko:en;
const validLetter=x=>x&&validLetterPassages(x)&&Object.hasOwn(ENDINGS,x.ending)&&typeof x.id==='string'&&x.id.length<=100&&typeof x.name==='string'&&x.name.length<=24&&typeof x.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&Number.isInteger(x.month)&&x.month>=0&&x.month<=96&&['close','reserved','distant'].includes(x.relationship)&&(x.fieldId===undefined||DISCIPLINES.some(d=>d.id===x.fieldId))&&(x.labMode===undefined||['dry','wet'].includes(x.labMode))&&(!Object.hasOwn(x,'labClosure')||validLabClosure(x.labClosure,x.month))&&(!x.cv||validateCVModel(x.cv))&&(!x.statistics||validStatistics(x.statistics))&&(!x.evidence||validEvidence(x.evidence))&&(!x.memories||Array.isArray(x.memories)&&x.memories.length<=16&&x.memories.every(h=>h&&h.kind==='event'&&EVENTS.some(e=>e.id===h.id)&&Number.isInteger(h.choice)&&h.choice>=0&&h.choice<EVENTS.find(e=>e.id===h.id).options.length&&Number.isInteger(h.month)&&h.month>=0&&h.month<=x.month));
function migrateLetter(x){if(!validLetter(x))return x;const out=structuredClone(x);if(out.statistics)out.statistics.student=mergeRelationship(out.statistics.student);if(out.cv?.statistics)out.cv.statistics.student=mergeRelationship(out.cv.statistics.student);return out;}
let loadNotice='',lang='ko',s=freshState(),gallery=[],seenPassageIds=[],letter=null,page=0,busy=false,storageOK=true,installPrompt=null,travelConsent=false,fast=false;
try{lang='ko';s=freshState();const raw=localStorage.getItem('pm-save-v4')||localStorage.getItem('pm-save-v3');if(raw){let parsed=null;try{parsed=migrateSave(JSON.parse(raw));}catch{}if(validateSave(parsed)){s=parsed;s.locale='ko';if(JSON.stringify(s)!==raw)localStorage.setItem('pm-save-v4',JSON.stringify(s));}else{try{localStorage.setItem('pm-save-unreadable',raw);}catch{}loadNotice='이전 저장을 이 버전에서 읽지 못해 따로 보관했습니다. 제작자에게 알려 주시면 복구를 돕겠습니다.';}}let storedPassages=[];try{storedPassages=JSON.parse(localStorage.getItem(LETTER_PASSAGES_KEY)||'[]');}catch{}if(Array.isArray(storedPassages)&&validPassageIds(storedPassages))seenPassageIds=storedPassages;const g=JSON.parse(localStorage.getItem('pm-letters-v3')||'[]');if(Array.isArray(g)){const migrated=migrateLetterGallery(g.map(migrateLetter).filter(validLetter),seenPassageIds);gallery=keepGallery(migrated.gallery);seenPassageIds=migrated.seenPassageIds;localStorage.setItem('pm-letters-v3',JSON.stringify(gallery));localStorage.setItem(LETTER_PASSAGES_KEY,JSON.stringify(seenPassageIds));}fast=localStorage.getItem('pm-fast')==='true';}catch{storageOK=false;}
let grantApplication={...(s.grantApplication??{role:'pi',years:3})};
function validIntakeDraft(value){const p=value?.profile,d=DISCIPLINES.find(d=>d.id===p?.fieldId);return value?.version===1&&Number.isInteger(value.intakeSeed)&&value.intakeSeed>=0&&value.intakeSeed<=0xffffffff&&(value.selected===null||Number.isInteger(value.selected)&&value.selected>=0&&value.selected<3)&&p&&['male','female','other'].includes(p.gender)&&Number.isInteger(p.age)&&p.age>=30&&p.age<=55&&d&&d.labModes.includes(p.labMode)&&['national','private','institute'].includes(p.institution)&&['beginner','realistic'].includes(p.difficulty)&&typeof value.professorName==='string'&&value.professorName.length>0&&value.professorName.length<=40;}
let intakeDraft=null;try{const saved=JSON.parse(localStorage.getItem(ADMISSION_KEY)||'null');if(!s.started&&validIntakeDraft(saved))intakeDraft=saved;}catch{}
function saveIntakeDraft(){try{intakeDraft?localStorage.setItem(ADMISSION_KEY,JSON.stringify(intakeDraft)):localStorage.removeItem(ADMISSION_KEY);}catch{storageOK=false;}}
const intakeOptions=draft=>({locale:'ko',professorGender:draft.profile.gender,professorProfile:{...draft.profile}});
let screenGuide=initialScreenGuide(),screenGuideFocus=null;try{const p=JSON.parse(localStorage.getItem(SCREEN_GUIDE_KEY)||'null');if(validScreenGuide(p))screenGuide=p;}catch{}
