const facultyLabel=k=>({research:t('학술활동','Scholarship'),teaching:t('교육','Teaching'),admin:t('학교행정','Administration'),mentoring:t('연구실 운영','Lab operations')}[k]);
const activityName=id=>id==='training'?t('군사교육소집','Military training'):id==='conference'&&s.month<24?'현장에서 배운다':id==='experiment'&&s.professorProfile?.labMode==='dry'?t('계산·모델링','Computation & modeling'):(ACTIVITIES[id]??LEGACY_ACTIVITIES[id])?.[lang]?.[0]||id;
const activityDescription=id=>id==='conference'&&s.month<24?'발표를 듣고 연구 현장의 질문과 분위기를 배웁니다.':id==='experiment'&&s.professorProfile?.labMode==='dry'?t('모형과 계산으로 가설을 검증한다.','Test a hypothesis with models and computation.'):(ACTIVITIES[id]??LEGACY_ACTIVITIES[id])?.[lang]?.[1]||'';
const calendarMonth=m=>((Math.min(m,95)+(lang==='ko'?2:8))%12)+1;
const year=m=>Math.floor(Math.min(m,95)/12)+1;
const professorAge=()=>Math.floor(facultyAge(s));
const monthName=m=>lang==='ko'?`${calendarMonth(m)}월`:new Intl.DateTimeFormat('en',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2000,calendarMonth(m)-1,1)));
const calendar=m=>t(`${year(m)}년차 ${monthName(m)}`,`Year ${year(m)} · ${monthName(m)}`);
function semester(m){const n=calendarMonth(m);return n>=3&&n<=6?t('봄학기','Spring semester'):n>=7&&n<=8?t('여름방학','Summer break'):n>=9&&n<=12?t('가을학기','Fall semester'):t('겨울방학','Winter break');}
const isFestival=()=>[4,10].includes(calendarMonth(s.month));
const isBreak=()=>[1,2,7,8].includes(calendarMonth(s.month));
