function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function archive(){
  if(!s.ending)return;const snapshot=structuredClone(s),id=(snapshot.creationSeed??snapshot.seed)+'-'+snapshot.month+'-'+snapshot.ending;
  let entry=gallery.find(x=>x.id===id);
  if(!entry){entry={id,ending:snapshot.ending,fieldId:snapshot.professorProfile.fieldId,labMode:snapshot.professorProfile.labMode,name:snapshot.name,date:new Date().toISOString().slice(0,10),month:snapshot.month,relationship:abilityScore(snapshot,'rapport')>=70?'close':abilityScore(snapshot,'rapport')>=40?'reserved':'distant',career:{...snapshot.career},endingReason:snapshot.endingReason,...(snapshot.labClosure?{labClosure:structuredClone(snapshot.labClosure)}:{}),statistics:endingStatistics(snapshot),evidence:endingEvidence(snapshot),memories:snapshot.history.filter(h=>h.kind==='event'&&EVENTS.some(e=>e.id===h.id)&&Number.isInteger(h.choice)&&h.choice>=0&&h.choice<EVENTS.find(e=>e.id===h.id).options.length).slice(-16).map(h=>({kind:'event',id:h.id,choice:h.choice,month:h.month}))};entry=prepareLetterPassages(entry,seenPassageIds);seenPassageIds=collectSeenPassageIds([entry],seenPassageIds);gallery.unshift(entry);gallery=keepGallery(gallery);}
  if(snapshot.labClosure)entry.labClosure??=structuredClone(snapshot.labClosure);entry.statistics??=endingStatistics(snapshot);entry.evidence??=endingEvidence(snapshot);entry.memories??=snapshot.history.filter(h=>h.kind==='event'&&EVENTS.some(e=>e.id===h.id)&&Number.isInteger(h.choice)&&h.choice>=0&&h.choice<EVENTS.find(e=>e.id===h.id).options.length).slice(-16).map(h=>({kind:'event',id:h.id,choice:h.choice,month:h.month}));
  if(snapshot.ending!=='gameover'&&!entry.cv){try{const result=await runEngine('cv',{state:snapshot});if(result)entry.cv=result.model;}catch(error){console.error('CV creation failed',error);}}
  if(entry.cv)entry.cv=upgradeCVModel(entry.cv,snapshot);
  save();return entry;
}
if(s.started)s.creationSeed??=s.seed;
archive();

function portrait(){return renderPortrait(weeklyAppearance(s));}
function facultyBar(k){const n=s.professor[k];return `<div class="stat ${n<20?'danger':''}"><div><span>${facultyLabel(k)}</span><strong>${Math.round(n)}<small> / 100</small></strong></div><div class="track" role="meter" aria-label="${facultyLabel(k)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(n)}"><span style="width:${n}%"></span></div></div>`;}
function degreeRequirements(){const st=visibleStage(),c=s.career,remaining=Math.max(0,Math.ceil(((st==='undergrad'?24:st==='masters'?s.mastersReviewAt:96)-s.month)/6));const targets=degreeTargets(s.professorProfile?.fieldId,st);let checks=st==='undergrad'?[[t('연구실 경험','Research experience'),t('진학 면담에서 결정','Decide at the admission meeting'),false]]:st==='masters'?[[t('논문 제출','Manuscripts submitted'),`${c.submissions} / ${targets.submissions}`,c.submissions>=targets.submissions],[t('학술 발표','Conference presentations'),`${c.conferences} / ${targets.conferences}`,c.conferences>=targets.conferences]]:[[t('논문 제출','Manuscripts submitted'),`${c.submissions} / ${targets.submissions}`,c.submissions>=targets.submissions],[t('논문 게재','Published papers'),`${c.papers} / ${targets.papers}`,c.papers>=targets.papers],[t('학술 발표','Conference presentations'),`${c.conferences} / ${targets.conferences}`,c.conferences>=targets.conferences],[t('자격시험 · 박사 진입 심사','Qualifying exam'),c.qual==='passed'?t('통과','Passed'):c.qual==='failed'?t('재응시 준비','Preparing a retake'):t('응시 예정','Upcoming'),c.qual==='passed']];return `<div class="degree-checks"><div class="degree-heading">${t('학위 진행 현황','Degree audit')}<span>${remaining}${t('학기 남음',' semesters left')}</span></div>${checks.map(([label,value,done])=>`<div><span>${label}</span><strong class="${done?'check-done':''}">${done?'✓ ':''}${value}</strong></div>`).join('')}</div>`;}
function sidebar(){return `<aside class="student-panel monthly-panel"><div class="panel-title">${t('지도학생','Your advisee')}<span class="record-id">PM–001</span></div><div class="student-id">${portrait()}<div><h2>${esc(name())}</h2><p>${phase()}</p><span>${genderName(s.gender)} · ${esc(getDiscipline(s.professorProfile?.fieldId).label)}</span></div></div><details class="student-details" ${innerWidth>=900?'open':''}><summary>학위·교수 업무·연구비 상세<span>${['research','teaching','admin','mentoring'].map(k=>`${facultyLabel(k)} ${Math.round(s.professor[k])}`).join(' · ')}</span></summary>${degreeRequirements()}<div class="faculty-overview"><p class="faculty-age">${esc(s.professorName||'지도교수')} · 현재 <strong data-professor-age>${professorAge()}세</strong></p><h3>${t('교수 업무 균형','Faculty workload balance')}</h3><div class="core-stats">${['research','teaching','admin','mentoring'].map(facultyBar).join('')}</div><p class="small-note">${t('업무가 0이 되면 학과장 면담으로 경고합니다. 3개월 연속 회복하지 못하면 운영이 종료됩니다.','A zero faculty score triggers a warning. Three consecutive months without recovery ends operations.')}</p></div>${difficultyNotice()}<dl class="student-numbers"><div><dt>${t('연구비 잔액','Research funds')}</dt><dd>${currency(s.lab.funds)}</dd></div><div><dt>학과 차입 미상환액</dt><dd>${currency(s.lab.debt??0)}</dd></div><div><dt>${t('인건비 계상률','Stipend allocation')}</dt><dd>${s.lab.budget.salary}%</dd></div><div><dt>h-index · 학술 인용</dt><dd>${s.impact?.hIndex??0} · ${(s.impact?.citations??[]).reduce((a,b)=>a+b,0)}회</dd></div><div><dt>학생인건비 통합관리 잔액</dt><dd>${currency(s.lab.pool??0)}</dd></div><div><dt>${t('수상 / 추천서','Awards / recommendations')}</dt><dd>${s.career.awards} / ${s.career.recommendations}</dd></div></dl></details>${s.sabbatical.active?`<p class="state-note">${t('연구년 중','On sabbatical')} · ${s.sabbatical.mode==='away'?t('해외·원격 지도','Abroad / remote advising'):t('국내 지도 유지','Advising from home')}</p>`:''}${lang==='ko'&&s.gender==='male'&&s.service.status!=='none'?`<p class="state-note">전문연 ${s.service.status==='planning'?'선발 준비 상담 중':s.service.status==='consulted'?'후속 복무 계획 상담 완료':'신청 계획 없음'}</p>`:''}</aside>`;}
function progress(){return `<div class="year-progress" aria-label="${t('8년의 지도기간','Eight-year timeline')}">${Array.from({length:8},(_,i)=>`<div class="year ${s.month>=i*12+12?'done':s.month>=i*12?'current':''}"><span>${i+1}${t('년','')}</span><i></i></div>`).join('')}</div><div class="progress-label"><span>${t('학부 1–2년 → 석사 3–4년 → 박사 5–8년','Undergraduate 1–2 → master’s 3–4 → PhD 5–8')}</span><span>${t('또는 석박사통합 3–8년','Or integrated MS/PhD 3–8')}</span></div>`;}
function venueControls(){return `<div class="venue-controls"><label>논문 투고 목표<select id="journal-target" ${s.project.submitted?'disabled':''}>${journalOptions(s.professorProfile.fieldId).map(([id,v])=>`<option value="${id}" ${s.project.journal===id?'selected':''}>${journalDescription(id,s.professorProfile.fieldId,s)}</option>`).join('')}</select></label><label>학술대회 목표<select id="conference-target">${Object.entries(CONFERENCE_TIERS).map(([id,v])=>`<option value="${id}" ${s.publication.conference===id?'selected':''}>${v.label}</option>`).join('')}</select></label><p>${journalProfile(s.professorProfile.fieldId).label} 분야의 가상 투고 기준입니다. IF(저널 영향력 지표)는 분야 내 저널 수준과 연도에 따라 달라지며, 투고 당시의 값을 기록합니다. 국내 등재지는 별도의 국내 발표 경로입니다. 도전적인 목표에는 더 충분한 연구와 발표 준비가 필요합니다.</p></div>`;}
function project(){const p=s.project,ph={...PROJECT_PHASES[p.phase],target:projectThresholds(s).phaseTargets[p.phase]};return `<section class="project-overview"><div class="section-top"><h2>${t('진행 중인 연구','Active research project')}</h2><span>${t('프로젝트','Project')} ${String(p.id).padStart(2,'0')} · ${s.career.completedProjects}${t('개 완료',' completed')}</span></div><h3>${esc(projectTitle(s,p.id,lang))}</h3>${venueControls()}<ol class="project-phases">${PROJECT_PHASES.map((x,i)=>`<li class="${i<p.phase?'done':i===p.phase?'current':''}"><span>${i<p.phase?'✓':i+1}</span>${x[lang]}</li>`).join('')}</ol><div class="project-current"><span>${ph[lang]}</span><span>${Math.min(100,Math.round(p.progress/ph.target*100))}% · ${p.conference?t('발표 완료','Presented'):t('발표 준비 중','Presentation pending')}</span></div><div class="project-track"><span style="width:${Math.min(100,p.progress/ph.target*100)}%"></span></div><p class="small-note">${p.phase===5?t('투고 후 심사 중입니다. 논문 쓰기로 수정 의견에 답할 수 있습니다.','Submitted and under review. Writing activities work on revisions.'):t('연구 주간의 수행 결과가 쌓이면 투고·발표를 준비할 수 있습니다. 완료 후 다음 질문으로 넘어갑니다.','Finish one project before beginning the next. Presentations and accepted papers are tracked separately.')}</p><p class="small-note">이번 연구 준비 ${Math.round(projectWork(s))} · 발표 기준 ${projectThresholds(s).conference} · 투고 기준 ${Math.round(projectThresholds(s).submission)}</p></section>`;}
function researchBudgetDetails(){const costs=researchOperatingCost(s,s.lab.budget,s.plan,{training:studentTrainingActive(s)}),conference=conferenceCosts(s),stipend=salaryBase()*s.lab.budget.salary/100;return `<div class="research-budget-profile"><strong>${esc(getDiscipline(s.professorProfile.fieldId).label)} · ${esc(costs.profile.label)}</strong><p>${esc(costs.profile.hint)}</p><dl class="budget-breakdown"><div><dt>기본 유지비</dt><dd>${currency(costs.fixed)}</dd></div><div><dt>환경·성과 지원</dt><dd>${currency(costs.support)}</dd></div><div><dt>계획한 연구 활동비</dt><dd>${currency(costs.activities)}</dd></div><div><dt>학생인건비</dt><dd>${currency(stipend)}</dd></div><div><dt>학회 참석비</dt><dd>${currency(conference.domestic+conference.overseas)}</dd></div></dl><p class="small-note">선택한 일정에 따라 연구 활동비가 달라집니다. 분석·정리하는 달과 실험·현장 조사를 하는 달의 지출을 다르게 계획하세요.</p></div>`;}
function grantPanel(){const g=s.grants,n=grantCounts(s),active=(g.portfolio??[]).filter(x=>x.end>s.month&&(x.id!==0||g.status==='active'));return `<details class="grant-panel"><summary><strong>연구과제·학생인건비 관리</strong><span>책임 ${n.pi} / 3 · 전체 ${n.total} / 5</span></summary><div class="grant-content"><p class="finance-profile-hint"><strong>${esc(researchFinanceProfile(s).label)}</strong> · ${esc(researchFinanceProfile(s).hint)}</p><ul class="grant-list">${active.map(x=>`<li><strong>${GRANT_TITLES[x.titleIndex]}</strong><span>${x.role==='pi'?'책임연구':'공동참여'} · ${Math.round((x.end-x.start)/12)}년 · ${Math.max(0,x.end-s.month)}개월 남음 · 다음 연차 예정액 ${currency(nextGrantAmount(x.annual,x.grantScaleVersion))}</span></li>`).join('')}</ul><dl><div><dt>운영비 잔액</dt><dd>${currency(s.lab.funds)}</dd></div><div><dt>학생인건비 통합관리 잔액</dt><dd>${currency(s.lab.pool??0)}</dd></div><div><dt>현재 지급액 / 월</dt><dd>${currency(salaryBase()*s.lab.budget.salary/100)}</dd></div></dl><div class="grant-application"><label>신청 역할<select id="grant-role"><option value="pi" ${grantApplication.role==='pi'?'selected':''}>책임연구자</option><option value="co" ${grantApplication.role==='co'?'selected':''}>공동참여 연구자</option></select></label><label>과제 기간<select id="grant-years">${[2,3,4,5].map(y=>`<option value="${y}" ${grantApplication.years===y?'selected':''}>${y}년</option>`).join('')}</select></label></div><p id="grant-annual-preview">이번 역할의 신규 과제 · 선정 시 연간 예정액 ${currency(applicationGrantAmount(s,grantApplication.role))}</p><p>“교수 업무·연구실 예산 조정”의 “이번 달 추가 활동”에서 “연구비 신청”을 선택하세요. 공모는 3월·9월에 열립니다. 한 달을 진행하면 선정 결과가 도착하고, 선정된 연구비는 입금 후 다음 연차마다 지급됩니다. 신규 과제는 책임연구 3개·전체 참여 5개의 범위에서 신청합니다. 진행 중인 기존 과제의 후속 신청은 기존 책임연구 자리를 대체합니다.</p><p>인건비는 통합관리계정에서 먼저 지급됩니다. 부족하면 운영비에서 충당하며, 적립한 인건비는 과제 종료 뒤에도 학생 지원에 남습니다. 겨울에는 연차보고를 준비하세요. 표시된 연차 예정액은 정상 보고 기준이며, 보고가 늦으면 실제 지급액이 줄어듭니다.</p><p class="small-note">${s.lab.financeMigration&&s.lab.financeMigration.original.funds+s.lab.financeMigration.original.pool>2000?`이전 재정 규칙의 잔액 합계 ${currency(s.lab.financeMigration.original.funds+s.lab.financeMigration.original.pool)}를 처음 불러올 때 2억원으로 조정했습니다. 원본 운영비·인건비 금액은 저장 기록에 보관되어 있습니다.`:''}</p><p class="small-note">${s.history.filter(h=>h.kind==='portfolio-selection').slice(-1).map(h=>`최근 신청: ${h.awarded?'선정':'미선정'} · ${h.years}년`).join('')}</p></div></details>`;}
function weeklyRestLabel(w){return w.criticalRest?t(`한계에 따른 회복 · ${restReasonText(w.recoveryCause)}`,`Recovery at a critical limit · ${restReasonText(w.recoveryCause)}`):w.assigned==='recovery'?t('합의한 회복 시간','Agreed recovery time'):'';}
function report(){
 const r=s.lastReport;if(!r)return '';
 const outcomes={training:'군사교육소집 · 학생 지도 중단',presentation_failed:'발표 준비를 돌아본다',explored:'여행·새로운 경험',completed:t('수행','Completed'),rested:t('충분히 쉬었다','Recovered'),talked:t('이야기를 나눴다','Talked together'),missed:t('수행하지 못했다','Could not complete'),failed:t('결과를 얻지 못했다','No result'),presented:t('학술 발표','Presented'),attended:t('청강·교류','Attended'),unprepared:t('발표를 준비하지 못했다','Not ready to present'),success:t('진척','Progress'),progress:t('연구 진척','Research progress'),recovered:t('충분히 쉬었다','Recovered'),not_completed:t('계획을 수행하지 못했다','Could not complete the plan'),inconclusive:t('유의미한 결과를 얻지 못했다','Inconclusive result'),preparing:t('발표 준비가 더 필요했다','Needs further preparation')};
 const consent=s.history.findLast(h=>h.kind==='rest-request-response'&&h.month===s.month-1),critical=r.results.filter(w=>w.criticalRest);
 const agreement=consent?t(consent.choice==='allow'?'학생의 휴식 요청을 받아들여 회복 시간을 확보했습니다.':'학생의 휴식 요청을 허용하지 않고 연구 계획을 유지했습니다. 부담과 스트레스가 커졌습니다.',consent.choice==='allow'?'The recovery request was honored and time for rest protected.':'The recovery request was declined and the research plan kept. Strain and stress increased.'):'';
 return `<details class="month-report"><summary>${t('지난달 수행 보고','Last month’s report')}<span>${r.suspended?t('연구비 부족으로 운영 보류 · 급여·연구 활동 미실행','Operations suspended for lack of funding; stipends and research paused'):`${r.borrowed>0?'학과 차입하며 진행 · ':''}${r.results.filter(x=>x.performed).length} / ${r.results.length} ${t('주 수행','weeks carried out')} · ${r.published?t('논문 게재','Paper published'):t('펼쳐서 확인','Open to inspect')}`}</span></summary>${r.borrowed>0?`<p class="borrowing-report-summary"><strong>학과 차입 ${currency(r.borrowed)}으로 운영을 이어 갔습니다.</strong> 급여와 연구 활동은 예정대로 진행했습니다. 미상환액 ${currency(r.debt??s.lab.debt??0)}${r.interest>0?` · 이번 달 차입 부담 ${currency(r.interest)}`:''}</p>`:''}${agreement?`<p class="rest-report-summary">${agreement}</p>`:''}${critical.length?`<p class="rest-report-summary critical-rest-warning"><strong>${t('수행 중 회복이 먼저 필요했습니다.','Recovery became necessary during the month.')}</strong> ${t('몸이나 마음이 한계에 이르러 일부 계획을 멈추고 쉬었습니다. 아래 주별 기록에서 원인을 확인하세요.','Some work stopped because physical or emotional reserves reached a critical limit. See the weekly reasons below.')}</p>`:''}<ol>${r.results.map((w,i)=>`<li><span>${i+1}${t('주차',' week')}</span><strong>${esc(activityName(w.proposed))}${w.proposed==='free'?` → ${{coursework:'시험 공부',study:'스스로 공부',experiment:'자율 연구',analysis:'자율 데이터 분석',rest:'휴식',travel:'여행·새로운 경험'}[w.autonomous]||'일정 다시 살피기'}`:''}</strong><em>${!w.suspended&&w.outcome!=='training'&&w.assigned&&w.assigned!=='free'&&w.assigned!=='recovery'&&w.actual!==w.assigned?`<span class="assignment-change">합의: ${esc(activityName(w.assigned))} → 실제: ${esc(activityName(w.actual))} · ${w.criticalRest?'회복 필요':w.deviation==='rest-needed'?'피로로 휴식':'미수행'}</span>`:''}${weeklyRestLabel(w)?`<span class="rest-outcome">${weeklyRestLabel(w)}</span>`:''}${w.suspended?t('연구비 부족 · 운영 보류','Funding shortage · operations suspended'):w.criticalRest?t('연구를 멈추고 회복','Research paused for recovery'):Number.isFinite(w.successRate)?`${researchGrade(w.successRate)} · ${Math.round(w.successRate*100)}%`:outcomes[w.outcome]||(w.performed?t('계획 수행','Carried out'):t('계획 변경·미수행','Changed / not completed'))}</em></li>`).join('')}</ol></details>`;
}

const feedbackOptions={praise:[['칭찬한다','Praise'],['지난달 잘한 점을 구체적으로 인정합니다.','Recognize last month’s work.']],listen:[['넘어간다','Move on'],['추가 평가 없이 이번 달 계획을 의논합니다.','Discuss the next plan without further evaluation.']],critique:[['지적한다','Critique'],['지난달의 병목과 보완할 부분을 짚습니다.','Discuss what needs improvement.']]};
function policyControls(){const p=s.policies??DEFAULT_POLICIES;return `<fieldset class="advising-policies"><legend>이번 달 지도 방침</legend><label>워라벨 · 출근 방식<select data-policy="work" ${studentTrainingActive(s)?'disabled':''}>${Object.entries(WORK_POLICIES).map(([id,label])=>`<option value="${id}" ${p.work===id?'selected':''}>${label}</option>`).join('')}</select></label><label>공부와 연구의 균형<select data-policy="study" ${studentTrainingActive(s)?'disabled':''}>${Object.entries(STUDY_POLICIES).map(([id,label])=>`<option value="${id}" ${p.study===id?'selected':''}>${label}</option>`).join('')}</select></label><p class="small-note">매달 면담에서 조정합니다. 긴 일정에는 피로가 쌓일 수 있습니다.</p></fieldset>`;}
function fundingResultNotice(){
 const notice=monthlyFundingNotice(s);if(!notice.results.length&&!notice.payments.length)return '';
 return `<section id="funding-results" class="funding-results" role="status" aria-label="연구과제 선정과 입금 소식"><h3>${notice.results.some(r=>r.awarded)?'좋은 소식! 연구과제가 선정되었습니다.':'이번 달 연구비 소식'}</h3>${notice.results.map(r=>`<article class="${r.awarded?'funding-awarded':'funding-rejected'}"><strong>${r.awarded?'선정':'미선정'} · ${esc(GRANT_TITLES[r.titleIndex]??'연구비 지원 과제')}</strong><p>${r.source==='renewal'?'기존 과제 후속 지원':'신규 과제'} · ${r.role==='co'?'공동참여':'책임연구'} · ${r.years}년${r.awarded?` · 연간 연구비 ${currency(r.annual)} · 이번 달 실제 입금 +${currency(r.paid)}`:''}</p><span>${r.awarded?'새 지원으로 연구를 이어 갈 여유가 생겼습니다. 다음 지출과 지원 기간을 확인하세요.':'이번 신청은 선정되지 않았습니다. 다음 공모와 지출 계획을 함께 살펴봅니다.'}</span></article>`).join('')}${notice.payments.map(r=>`<article class="funding-awarded"><strong>연차 연구비 입금 · ${esc(GRANT_TITLES[r.titleIndex]??'진행 중인 과제')}</strong><p>이번 달 실제 입금 +${currency(r.amount)}</p><span>진행 중인 과제의 연차 지원입니다.</span></article>`).join('')}${notice.gross>0?`<p class="funding-deposit-summary">이번 달 총 연구비 입금 +${currency(notice.gross)}${notice.repaid>0?` · 이 중 차입 상환 ${currency(notice.repaid)}`:''}<br>학생인건비 적립과 차입 상환을 반영하므로 운영 현금의 증가분은 총 입금액과 다를 수 있습니다.</p>`:''}</section>`;
}
function creditBlocks(key,count){const capacity=facultyCapacity(s).credits,used=Object.values(s.allocation).reduce((a,b)=>a+b,0);return `<span class="credit-blocks" role="group" aria-label="${facultyLabel(key)} 크레딧">${Array.from({length:capacity},(_,i)=>`<button type="button" data-credit="${key}" data-count="${i+1}" aria-label="${facultyLabel(key)} ${i+1}크레딧" aria-pressed="${i<count}" ${i>=count&&used-count+i+1>capacity?'disabled':''}>${i+1}</button>`).join('')}<output>${count}</output></span>`;}
function renderPlanningControl(selector){const open=$('.management-controls')?.open;render();if(open&&$('.management-controls'))$('.management-controls').open=true;$(selector)?.focus({preventScroll:true});}
function toggleCredit(button){const key=button.dataset.credit,target=Number(button.dataset.count),before=s.allocation[key],next=target<=before?target-1:target;if(Object.values(s.allocation).reduce((a,b)=>a+b,0)-before+next>facultyCapacity(s).credits)return;s.allocation[key]=next;save();renderPlanningControl(`[data-credit="${key}"][data-count="${target}"]`);}
function planBlockMessage(status){const messages={workload:t(`교수 업무 ${status.allocated}크레딧을 ${status.capacity}크레딧 이내로 조정하세요.`,`Reduce faculty workload from ${status.allocated} to ${status.capacity} credits.`),'grant-call':t('연구비 신청은 3월·9월에 가능합니다. 이번 달 추가 활동을 바꾸세요.','Funding calls open in March and September. Choose another faculty activity this month.'),'grant-limit':t('선택한 역할은 3책5공 한도에 도달했습니다. 신청 역할 또는 이번 달 추가 활동을 바꾸세요.','This grant role exceeds the 3 PI / 5 total limit. Change the role or faculty activity.')};return status.blockers.map(k=>messages[k]).filter(Boolean).join(' ');}
function financePlanWarning(status){return status.estimatedBorrowing>0?t(`부족액 ${currency(status.estimatedBorrowing)}을 학과에서 자동 차입해 한 달을 진행합니다. 이후 연구비 입금으로 자동 상환합니다. 학생인건비 풀은 운영비로 사용할 수 없습니다. 미상환액이 1천만원을 넘은 상태에서 추가 차입이 3개월 연속 이어지면 운영이 종료됩니다.`,`The department automatically lends the ${currency(status.estimatedBorrowing)} shortfall so the month can proceed. Future grant deposits repay it. Stipend funds cannot pay operating expenses. Three consecutive months of new borrowing while debt exceeds KRW 10 million ends operations.`):'';}
function planNoticeMessage(status){return [planBlockMessage(status),financePlanWarning(status)].filter(Boolean).join(' ');}
function restReasonText(reason){return reason==='both'?t('몸과 마음이 모두 지쳐 있습니다.','Both physical and emotional reserves are low.'):reason==='physical'?t('몸이 지쳐 회복이 필요합니다.','Physical fatigue calls for recovery.'):reason==='stress'?t('스트레스가 높고 몸이나 마음의 회복 여력이 부족합니다.','Stress is high and physical or emotional reserves are too low.'):t('마음의 여유가 부족해 회복이 필요합니다.','Emotional reserves are low and need time to recover.');}
function currentRestConsent(){return s.restConsent?.month===s.month?s.restConsent:null;}
function recoveryStatus(recovery=recoveryPlan(s)){
 const consent=currentRestConsent();
 if(consent?.choice==='decline')return t('이번 달은 계획을 유지하기로 했습니다. 부담이 커졌으니 다음 수행 보고를 살펴 주세요.','The plan stays in place this month. Watch the next report for the increased strain.');
 if(consent?.choice==='allow')return recovery.missing.length?t(`합의한 휴식 중 ${recovery.missing.length}주가 일정에서 빠졌습니다. 휴식 시간을 다시 확보할 수 있습니다.`,`${recovery.missing.length} agreed recovery weeks are missing. You can restore them.`):t('이번 달 휴식을 허용했습니다. 연구에 쓰는 시간을 줄이고 회복을 먼저 챙깁니다.','Recovery is agreed for this month. Research time is reduced to make room for rest.');
 return t('이번 달 진행 전에 요청을 허용할지 함께 결정합니다.','Discuss the request before this month begins.');
}
function recoveryNotice(){
 const recovery=recoveryPlan(s),{request,missing}=recovery,consent=currentRestConsent();
 if(!request&&!consent)return '';
 const reason=request?.reason??consent.reason,weeks=request?.weeks??consent.weeks,critical=criticalRestCause(s);
 const action=!consent?'discuss':consent.choice==='allow'&&missing.length?'restore':null;
 return `<aside class="recovery-plan-notice" aria-labelledby="recovery-heading"><div><strong id="recovery-heading">${consent?t('이번 달 휴식에 대한 합의','This month’s recovery agreement'):t('학생이 회복 시간을 요청했습니다.','Your student has requested recovery time.')}</strong><p>${restReasonText(reason)} ${t(`${weeks}주 정도 쉬고 싶다고 합니다. 시험·학회 등 고정 일정도 함께 확인하세요.`,`They would like about ${weeks} weeks of rest. Review fixed exams and conferences together.`)}</p>${critical?`<p class="critical-rest-warning" role="alert"><strong>${t('지금은 회복을 우선해야 합니다.','Recovery needs to come first.')}</strong> ${restReasonText(critical)} ${t('몸이나 마음이 한계에 이른 상태입니다. 계획을 유지하더라도 수행 중에는 연구를 멈추고 쉬게 될 수 있습니다.','The student is at their limit. Work may pause for recovery even if the plan is kept.')}</p>`:''}<span id="recovery-plan-status" role="status" aria-live="polite">${recoveryStatus(recovery)}</span></div><button type="button" class="secondary" data-ui="respect-rest" ${action?'':'hidden disabled'}>${action==='restore'?t('합의한 휴식 복원','Restore agreed recovery'):t('휴식 요청 함께 의논','Discuss the rest request')}</button></aside>`;
}
function focusNextDecision(){const target=$('#decision h2')||$('#monthly-plan h2');if(target){target.tabIndex=-1;target.focus({preventScroll:true});target.scrollIntoView({behavior:motionAllowed()?'smooth':'auto',block:'start'});}}

function stepper(group,key,value,min,max,label,step=1){return `<span class="touch-stepper"><button type="button" data-adjust="${group}" data-key="${key}" data-delta="-${step}" aria-label="${esc(label)} 줄이기" ${value<=min?'disabled':''}>−</button><input type="number" readonly tabindex="-1" inputmode="none" data-${group}="${key}" min="${min}" max="${max}" value="${value}" aria-label="${esc(label)}"><button type="button" data-adjust="${group}" data-key="${key}" data-delta="${step}" aria-label="${esc(label)} 늘리기" ${value>=max?'disabled':''}>+</button></span>`;}
function adjustControl(button){const group=button.dataset.adjust,key=button.dataset.key,input=$(`[data-${group}="${key}"]`),value=Math.max(Number(input.min),Math.min(Number(input.max),Number(input.value)+Number(button.dataset.delta)));if(group==='budget'&&key==='salary'&&calendarMonth(s.month)!==3)return;if(group==='allocation')s.allocation[key]=value;else s.lab.budget[key]=value;input.value=value;input.closest('.touch-stepper').querySelectorAll('button').forEach(b=>b.disabled=Number(b.dataset.delta)<0?value<=Number(input.min):value>=Number(input.max));updateCosts();save();if($('#live-stage')&&!busy)$('#live-stage').innerHTML=idleLabScene(s);}
function storyObjective(){const chapter=s.month<24?'1 · 첫 연구실':s.month<48?'2 · 자기 질문을 찾는 시간':s.month<84?'3 · 독립하는 연구자':'4 · 연구실 밖의 다음 장';const goal=s.month<24?'수업의 기초와 연구 경험을 쌓고 진학을 의논합니다.':s.route==='masters'&&s.month<48?'석사논문 초안과 발표를 준비하고 다음 진로를 의논합니다.':s.career.qual!=='passed'?'연구 질문과 기초를 정리해 박사 자격시험을 준비합니다.':'연구성과를 정리하며 학위논문과 이후의 삶을 준비합니다.';return `<section class="story-objective"><span>메인스토리 ${chapter}</span><strong>${goal}</strong><small>수업 · 연구 · 자율 시간의 균형을 함께 살펴 주세요.</small></section>`;}
function conferenceControls(){const abroad=[2,8].includes(calendarMonth(s.month)),domestic=normalizedDomesticAttendance(s,s.attendance.domestic),away=professorAbroad(s);return `${isFestival()?`<section class="attendance-panel domestic-conference-summary" aria-label="확정된 국내학회 참석 계획"><strong>${monthName(s.month)} 셋째 주 국내학회 · ${ATTENDANCE_LABELS[domestic]}</strong><p>참석 경비 <span id="domestic-conference-cost">${currency(conferenceCosts(s).domestic)}</span> · 전월 면담에서 정한 계획입니다. ${studentAttends(domestic)?'학생은 해당 주에 청강·발표를 합니다.':'학생은 자신의 일정을 이어갑니다.'}${away?' 해외 연구년 중이므로 교수는 국내학회에 참석하지 않습니다. 이전 동반 계획은 학생 단독 참석으로 조정합니다.':''}</p></section>`:''}${abroad?`<section class="attendance-panel"><label>해외학회 참석 · 1인 400만원<select id="overseas-attendance">${Object.entries(ATTENDANCE_LABELS).map(([id,label])=>`<option value="${id}" ${s.attendance.overseas===id?'selected':''} ${studentAttends(id)&&(!canTravel(s)||studentTrainingActive(s))?'disabled':''}>${label} · ${({none:0,professor:400,together:800,student:400})[id]}만원${studentAttends(id)&&!canTravel(s)?' · 초록 채택 후 가능':''}</option>`).join('')}</select></label><p>학생 발표는 초록 채택 후 가능합니다. 학생이 가면 마지막 주를 학회 일정으로 확보합니다.</p></section>`:''}`;}
const abroadWeek=i=>studentAttends(s.attendance?.overseas)&&canTravel(s)&&i===s.plan.length-1;
function schedule(){const proposed=proposeSchedule(s),restRequest=studentRestRequest(s),total=Object.values(s.allocation).reduce((a,b)=>a+b,0),status=planReadiness(s,grantApplication),enough=status.ready,shared=s.professorGender!=='unspecified'&&s.professorGender===s.gender;return `<section id="monthly-plan" class="schedule monthly-schedule"><div class="section-top"><h2>${t('주별 지도계획','Weekly advising plan')}</h2><span>${t(`이번 달 ${s.plan.length}주 · 클릭해서 학생의 제안을 조정합니다.`,`${s.plan.length} weeks this month · discuss the proposal.`)}</span></div>${studentTrainingActive(s)?'<aside class="state-note" role="status"><strong>겨울방학 군사교육소집 · 3주</strong><p>학생 지도·면담과 학습·연구 일정은 진행하지 않습니다. 복귀 후 남은 주는 학생이 자율적으로 계획합니다. 교수의 학술·행정 업무는 계속할 수 있습니다.</p></aside>':''}${recoveryNotice()}${conferenceControls()}${isFestival()&&studentAttends(s.attendance.domestic)?`<div class="festival-notice"><strong>${monthName(s.month)} ${t('셋째 주 학술대회','conference · week 3')}</strong><span>${t('1·2주 준비 → 3주 발표·청강 → 남은 주 회복','Prepare in weeks 1–2 → present or attend in week 3 → recover in week 4')}</span></div>`:''}<div class="weekly-planner">${s.plan.map((id,i)=>`<div class="week-plan ${abroadWeek(i)||weekContext(s,i,s.plan.length).conference&&studentAttends(s.attendance.domestic)?'conference-week':weekContext(s,i,s.plan.length).exam?'exam-week':''}"><div class="week-heading"><strong>${i+1}${t('주차',' week')}</strong><span>${abroadWeek(i)?'해외학회 주간':isFestival()&&i===2&&studentAttends(s.attendance.domestic)?t('고정 학술대회','Fixed conference'):weekContext(s,i,s.plan.length).exam?weekContext(s,i,s.plan.length).examType:`${academicWeeks(s)[i]?.start.slice(5).replace('-','/')} · 학사 ${academicWeeks(s)[i]?.number}주`}</span></div><p class="proposal">${t('학생 제안','Student proposes')}<br><strong>${activityName(proposed[i])}</strong>${proposed[i]==='free'&&examWindow(s,i,s.plan.length)?'<span class="autonomy-request">시험 준비는 제 방식대로 해 보고 싶어요.</span>':''}${restRequest&&proposed[i]==='recovery'?`<span class="autonomy-request rest-request">${t('휴식 요청 · 쉬면서 회복하고 싶어요.','Rest requested · I would like time to recover.')}</span>`:''}</p><label for="week-${i}">${t('합의한 일정','Agreed schedule')}</label><select id="week-${i}" data-week="${i}" ${studentTrainingActive(s)||abroadWeek(i)||isFestival()&&i===2&&studentAttends(s.attendance.domestic)?'disabled':''}>${studentTrainingActive(s)?`<option value="${id}">${i<3?'군사교육소집 · 지도 불가':'복귀 후 자율 시간'}</option>`:abroadWeek(i)?`<option value="${id}">해외학회 참석</option>`:Object.entries(ACTIVITIES).filter(([key])=>(key!=='teach'||s.month>=24)&&(key!=='conference'||studentAttends(s.attendance.domestic)&&availableActivities(s,i,s.plan.length).conference)).map(([key,a])=>`<option value="${key}" ${id===key?'selected':''}>${activityName(key)}</option>`).join('')}</select><p class="week-desc">${abroadWeek(i)?'채택된 초록을 발표하고 새 연구자들과 교류합니다.':weekContext(s,i,s.plan.length).important?'시험 준비가 중요한 주간입니다. 공부와 회복을 먼저 살펴 주세요.':activityDescription(id)}</p></div>`).join('')}</div><section class="operating-credit"><h3>부족한 연구비는 학과에서 자동 차입합니다.</h3><p>운영 잔액 ${currency(s.lab.funds)} · 미상환 차입금 ${currency(s.lab.debt??0)}</p><small>별도 신청 없이 부족액을 충당해 한 달을 진행합니다. 이후 연구비 입금으로 자동 상환하며, 학생인건비 풀은 운영비·상환에 사용할 수 없습니다. 미상환액이 1천만원을 넘은 채 추가 차입이 3개월 연속 지속되면 운영이 종료됩니다.</small></section>${policyControls()}<div class="meeting-feedback"><div class="section-top"><h3>${t('이번 면담의 연구 피드백','Feedback at this meeting')}</h3><span>${t('지난달의 수행 보고를 바탕으로','Based on last month’s report')}</span></div><div class="feedback-options">${Object.entries(feedbackOptions).map(([id,txt])=>`<label class="feedback-option ${s.feedback===id?'selected':''}"><input type="radio" name="feedback" ${studentTrainingActive(s)?'disabled':''} value="${id}" ${s.feedback===id?'checked':''}><strong>${txt[0][lang==='ko'?0:1]}</strong><span>${txt[1][lang==='ko'?0:1]}</span></label>`).join('')}</div></div><section id="faculty-allocation" class="faculty-credit-panel"><fieldset><legend>${t('교수의 업무 배분','Faculty workload allocation')}</legend><p>${t(`최대 ${facultyCapacity(s).credits}크레딧 · 블록을 눌러 배분합니다. 남겨 두어도 괜찮습니다.`,`Activate blocks within ${facultyCapacity(s).credits} credits. Unused credits are allowed.`)}</p>${Object.entries(s.allocation).map(([k,n])=>`<label class="allocation-row"><span>${facultyLabel(k)}</span>${creditBlocks(k,n)}</label>`).join('')}<p class="workload-context">${facultyCapacity(s).sabbatical?'연구년 · 교육 의무 일시 해제':facultyCapacity(s).vacation?'방학 · 교육 유지 부담 완화':'학기 중 · 교육을 우선 배정해 주세요.'} · 업무 반영 ${Math.round(facultyCapacity(s).efficiency*100)}%${facultyCapacity(s).jitter?' · 일정 변동 '+(facultyCapacity(s).jitter>0?'+':'')+facultyCapacity(s).jitter+'크레딧':''}</p><p id="allocation-total" class="${total>facultyCapacity(s).credits?'danger-text':''}">${t('합계','Total')} ${total} / ${facultyCapacity(s).credits}</p></fieldset></section><details id="lab-budget" class="management-controls"><summary>${t('교수 업무·연구실 예산 조정','Adjust faculty workload & lab budget')}<span>${t('예산과 업무 배분은 다음 달에도 유지됩니다.','Allocations carry forward to the next month.')}</span></summary><div id="research-budget-details">${researchBudgetDetails()}</div><div class="management-grid"><fieldset><legend>${t('연구비 집행 계획','Research expenditure')}</legend><p>${t('인건비 계상률은 매년 3월, 운영 집행은 매달 조정합니다.','Stipend rate changes in March; operations are adjusted each month')}</p><label class="budget-row"><span>${t('학생인건비 계상률','Stipend allocation rate')}</span>${calendarMonth(s.month)===3?stepper('budget','salary',s.lab.budget.salary,0,100,'학생인건비 계상률',5):`<strong>${s.lab.budget.salary}% · 다음 3월에 조정</strong>`}</label><p id="stipend-amount">${t('학생인건비','Monthly stipend')} ${currency(salaryBase()*s.lab.budget.salary/100)}</p>${[['environment',t('연구환경','Research environment')],['performance',t('연구성과 지원','Research support')]].map(([k,label])=>`<label class="budget-row"><span>${label}</span>${stepper('budget',k,s.lab.budget[k],0,6,label)}</label>`).join('')}<p id="expense-amount">${t('이번 달 예상 지출','Estimated expenditure')} ${currency(estimate())}</p></fieldset></div><div class="faculty-special"><p class="abstract-status">해외학회: ${({none:'방학 첫 달에 초록을 제출할 수 있습니다.',review:'초록 심사 중',accepted:'초록 채택 · 연구비와 이번 달 일정을 확인해 주세요.',rejected:'이번 초록은 미채택 · 다음 학회에서 다시 도전할 수 있습니다.',attended:'발표와 교류를 마쳤습니다.',expired:'이번 학회는 참석하지 않고 다음 기회를 준비합니다.'})[s.travel?.status??'none']}</p><label for="faculty-action">${t('이번 달 교수의 추가 활동','Additional faculty activity')}</label><select id="faculty-action"><option value="routine" ${s.facultyAction==='routine'?'selected':''}>${t('평소의 학술·교육 활동','Routine scholarship & teaching')}</option>${[1,7].includes(calendarMonth(s.month))&&s.month>=24?`<option value="abstract" ${s.facultyAction==='abstract'?'selected':''}>해외학회 초록 투고 · 다음 달 채택 결과</option>`:''}<option value="report" ${s.facultyAction==='report'?'selected':''}>연차보고서 작성·산학협력단 정산 준비</option><option ${grantCallOpen(s)?'':'disabled'} value="funding" ${s.facultyAction==='funding'?'selected':''}>${t('연구비 신청 · 제안서 제출','Apply for additional funding')}</option><option value="recommend" ${s.facultyAction==='recommend'?'selected':''}>${t('추천서 쓰기 · 논문 게재 후 1년에 1회 인정','Write a recommendation · once a year after publication')}</option><option ${studentTrainingActive(s)?'disabled':''} value="conversation" ${s.facultyAction==='conversation'?'selected':''}>학생과 대화·안부 확인</option><option ${studentTrainingActive(s)?'disabled':''} value="support" ${s.facultyAction==='support'?'selected':''}>${t('학생 지원·원격 면담 강화','Extra student support / remote advising')}</option></select></div></details><div class="monthly-confirm"><div><strong>${t('이번 달 예상 지출','Estimated monthly cost')} <span id="confirm-cost">${currency(estimate())}</span></strong><small id="confirm-borrowing" class="confirm-borrowing ${status.estimatedBorrowing?'':'hidden'}">부족액 ${currency(status.estimatedBorrowing)} 자동 차입</small><span>${t('일정 수행은 체력·의욕·관계에 따라 달라집니다.','Execution depends on energy, motivation and trust.')}</span></div><button class="primary" data-ui="advance" aria-describedby="budget-error" ${busy||!validateSave(s)||total>facultyCapacity(s).credits||!enough?'disabled':''}>${t('일정 확정 · 한 달 진행','Agree & advance one month')} →</button></div><div class="budget-error ${enough&&!status.estimatedBorrowing?'hidden':''}" id="budget-error" role="status" aria-live="polite"><p data-plan-block>${planNoticeMessage(status)}</p><button class="text-button" type="button" data-ui="review-plan">${t('업무·예산 조정으로 이동','Review workload and budget')} →</button></div></section>`;}
function difficultyNotice(){const d=difficultySettings(s);return `<aside class="difficulty-status" aria-label="현재 난도"><strong>${esc(d.label)}</strong>${d.id==='beginner'&&s.month<d.supportUntil?`<span>시작 연구비 최소 ${currency(d.supportFloor)} · 정착지원 첫 ${d.supportUntil}개월</span><p>필수 인건비·실험실 유지비가 부족한 달에만 정착지원 · 이번 달 최대 ${currency(Math.min(d.monthlySupport,d.remainingSupport))}, 남은 한도 ${currency(d.remainingSupport)}</p>`:'<span>추가 정착지원 없음 · 연구과제와 운영 계획으로 관리합니다.</span>'}</aside>`;}
function onboardingFlow(){return renderOnboardingFlow();}
function screenGuideInvite(){return screenGuide.status==='available'&&!s.pending&&!s.ending?`<aside class="screen-guide-invite"><div><strong>연구실 화면이 처음이신가요?</strong><p>메뉴와 월별 계획을 실제 화면에서 짧게 안내합니다.</p></div><button class="secondary" type="button" data-ui="screen-guide-start">화면 안내 보기 →</button><button class="text-button" type="button" data-ui="screen-guide-skip">나중에 보기</button></aside>`:'';}
function syncOnboardingUpdate(){
 $('#onboarding-update')?.remove();document.body.classList.remove('update-notice-active');document.documentElement.style.removeProperty('--update-notice-space');
 if(!showReleaseNotice||busy||!(view()==='home'||!s.started&&view()==='lab'))return;
 const panel=document.createElement('aside');panel.id='onboarding-update';panel.className='onboarding-update';panel.setAttribute('aria-labelledby','update-notice-title');panel.innerHTML=renderUpdateNotice();
 document.body.append(panel);document.body.classList.add('update-notice-active');document.documentElement.style.setProperty('--update-notice-space',`${Math.ceil(panel.getBoundingClientRect().height+80)}px`);
}
function syncScreenGuide(){
 const next=screenGuideForRun(screenGuide,s);if(JSON.stringify(next)!==JSON.stringify(screenGuide)){screenGuide=next;saveScreenGuide();}
 document.querySelectorAll('.screen-guide-target').forEach(el=>el.classList.remove('screen-guide-target'));
 $('#screen-guide')?.remove();document.body.classList.remove('screen-guide-active');document.documentElement.style.removeProperty('--screen-guide-space');
 if(view()!=='lab'||!s.started||s.pending||s.ending||busy||screenGuide.status!=='active') {history.scrollRestoration='auto';screenGuideFocus=null;return;}history.scrollRestoration='manual';
 const step=SCREEN_GUIDE_STEPS[screenGuide.step];if(step.open){const panel=$(step.open);if(panel)panel.open=true;}
 const target=$(step.selector)||$(step.fallback)||$('#monthly-plan');if(!target)return;
 target.classList.add('screen-guide-target');
 const guide=document.createElement('aside');guide.id='screen-guide';guide.className='screen-guide';guide.setAttribute('aria-labelledby','screen-guide-title');guide.innerHTML=`<div class="screen-guide-top"><span>첫 면담 화면 안내 · ${screenGuide.step+1} / ${SCREEN_GUIDE_STEPS.length}</span><button type="button" class="text-button" data-ui="screen-guide-skip">건너뛰기</button></div><h2 id="screen-guide-title" tabindex="-1">${esc(step.title)}</h2><p>${esc(step.body)}</p><div class="screen-guide-actions"><button type="button" class="secondary" data-ui="screen-guide-back" ${screenGuide.step===0?'disabled':''}>← 뒤로</button><button type="button" class="primary" data-ui="screen-guide-next">${screenGuide.step===SCREEN_GUIDE_STEPS.length-1?'안내 마치기':'다음 →'}</button></div>`;
 document.body.append(guide);document.body.classList.add('screen-guide-active');document.documentElement.style.setProperty('--screen-guide-space',`${Math.ceil(guide.getBoundingClientRect().height+80)}px`);
 const key=screenGuide.runKey+'-'+screenGuide.step;if(key!==screenGuideFocus){screenGuideFocus=key;requestAnimationFrame(()=>{if(!target.isConnected||!guide.isConnected)return;const bar=$('.faculty-scroll-summary')?.getBoundingClientRect().height??0,rect=target.getBoundingClientRect(),available=guide.getBoundingClientRect().top-bar-24;const offset=bar+16+Math.max(0,(available-Math.min(rect.height,available))/2);window.scrollTo({top:Math.max(0,window.scrollY+rect.top-offset),behavior:'auto'});$('#screen-guide-title')?.focus({preventScroll:true});});}
}
function difficultySelector(){return `<fieldset class="difficulty-setup"><legend>이번 연구실의 난도</legend><div class="difficulty-options"><label class="difficulty-option selected"><input type="radio" name="difficulty" value="beginner" checked aria-describedby="difficulty-beginner-hint"><span><strong>신임교수 (쉬움)</strong><small id="difficulty-beginner-hint">초기 연구비 최소 8천만원. 1–2년차 필수 인건비·실험실 유지비가 부족할 때 제한된 정착지원.</small></span></label><label class="difficulty-option"><input type="radio" name="difficulty" value="realistic" aria-describedby="difficulty-realistic-hint"><span><strong>현실 (보통)</strong><small id="difficulty-realistic-hint">기존 연구비 규칙. 추가 정착지원 없이 과제와 교수 업무를 운영합니다.</small></span></label></div><p id="difficulty-hint" class="small-note" role="status" aria-live="polite">쉬움 · 첫 24개월, 정착지원 총 3천만원 중 한 달 최대 300만원을 필수 지출 부족액만큼 지원합니다.</p></fieldset>`;}
function updateDifficultySetup(){const selected=$('input[name="difficulty"]:checked')?.value??'beginner';document.querySelectorAll('.difficulty-option').forEach(el=>el.classList.toggle('selected',el.querySelector('input').checked));$('#difficulty-hint').textContent=selected==='beginner'?'쉬움 · 첫 24개월, 정착지원 총 3천만원 중 한 달 최대 300만원을 필수 지출 부족액만큼 지원합니다.':'보통 · 기존과 같은 연구비 난도입니다. 업무가 0이 되면 두 달의 회복 기간 뒤 운영 종료를 판단합니다.';}
function labRiskNotice(){if(s.ending)return '';const {items}=labRiskStatus(s);if(!items.length)return '';return `<aside class="notice warning lab-risk-notice" role="status" aria-labelledby="lab-risk-heading"><strong id="lab-risk-heading">연구실 운영 경고 · 회복할 시간을 확보하세요</strong><ul>${items.map(item=>`<li><strong>${esc(item.label)}</strong> · ${item.streak?`${item.streak}개월 연속 · 운영 종료까지 남은 ${item.remaining}개월`:'이번 달 업무 배분을 점검하세요'}<p>${esc(item.advice)}</p></li>`).join('')}</ul><p>연구비 부족분은 자동 차입해 진행할 수 있습니다. 미상환액 1천만원 초과 상태의 추가 차입이나, 직접 선택한 운영 보류가 3개월 연속 이어지면 운영이 종료됩니다.</p>${!s.pending?'<button class="secondary" type="button" data-ui="review-plan">업무·예산 조정으로 이동 →</button>':''}</aside>`;}
function endingCause(entry){return entry?.ending==='gameover'?`<p class="closure-cause" role="status"><strong>종료 원인</strong> · ${esc(closureSummary(entry,lang))}</p>`:'';}
function suspendedControl(){if(s.ending||s.pending||!essentialLabStatus(s).blocked)return '';return `<aside class="suspension-notice" aria-labelledby="suspension-heading"><strong id="suspension-heading">필수 운영비도 부족합니다.</strong><p>한 달 진행 버튼을 누르면 부족분을 자동 차입해 급여와 연구를 이어 갑니다. 지출을 줄이고 입금을 기다리기로 했다면 아래에서 운영 보류를 선택할 수도 있습니다. 직접 보류하면 급여·연구·학습 성과가 진행되지 않으며, 3개월 연속 보류하면 운영이 종료됩니다.</p><button class="secondary" type="button" data-ui="suspend" aria-describedby="suspension-heading">운영을 보류하고 다음 달로 →</button></aside>`;}
function welcome(){
  if(intakeDraft)return admissionInterview();
  const fieldOptions=[...new Set(DISCIPLINES.map(d=>d.group))].map(group=>`<optgroup label="${esc(group)}">${DISCIPLINES.filter(d=>d.group===group).map(d=>`<option value="${d.id}" ${d.id==='050'?'selected':''}>${esc(d.label)}</option>`).join('')}</optgroup>`).join('');
  return `<section class="welcome"><h2>새 학기, 함께 연구할 학생을 만납니다.</h2><p>응원하고 함께 배우는 여덟 번의 봄.</p><button type="button" class="text-button update-replay" data-ui="update-open">${RELEASE_NOTES_VERSION} 변경사항 다시 보기 →</button><form id="start-form">
    ${onboardingFlow()}${difficultySelector()}<fieldset class="professor-setup"><legend>교수님의 연구실</legend><div class="setup-grid">
      <label>교수님 호칭<select name="professorName"><option value="지도교수">지도교수</option><option value="김 교수">김 교수</option><option value="이 교수">이 교수</option><option value="박 교수">박 교수</option><option value="최 교수">최 교수</option><option value="정 교수">정 교수</option><option value="custom">성씨 직접 입력</option></select><input name="professorSurname" id="professor-surname" class="hidden" placeholder="성씨 (예: 김, 남궁)" maxlength="4" pattern="[가-힣]{1,4}" autocomplete="off" aria-label="교수님 성씨"></label><label>성별<select name="professorGender"><option value="female">여성</option><option value="male" selected>남성</option><option value="other">기타</option></select></label>
      <label>연령 (30–55)<select name="professorAge">${Array.from({length:26},(_,i)=>`<option value="${i+30}" ${i===8?'selected':''}>${i+30}세</option>`).join('')}</select></label>
      <label>연구 분야<select name="fieldId" id="field-id">${fieldOptions}</select></label>
      <label>연구 방식<select name="labMode" id="lab-mode"><option value="dry">Dry lab · 이론·계산</option><option value="wet">Wet lab · 실험</option></select></label>
      <label>소속학교<select name="institution"><option value="national">국립대</option><option value="private">사립대</option><option value="institute">과학기술원 · 연구 중심</option></select></label>
    </div><p id="profile-hint" class="small-note">국립대 · 행정 부담 높음(빠른 감소) / 학술활동 요구 보통</p></fieldset>
    <fieldset class="admission-seed-setup"><legend>공유받은 학생이 있나요?</legend><label for="admission-share-code">학생 공유 코드 (선택)</label><input id="admission-share-code" name="admissionShareCode" placeholder="PM-1234ABCD-1" pattern="[Pp][Mm]-[0-9A-Fa-f]{8}-[1-3]" maxlength="13" autocomplete="off"><p class="small-note">비워 두면 이번 입학면접의 세 후보를 새로 준비합니다. 같은 코드를 넣으면 같은 후보를 만납니다. 면접을 열면 후보와 교수 설정이 그대로 보관됩니다.</p></fieldset>
    <div class="telemetry-choice"><label><input type="checkbox" id="analytics-consent" ${analyticsConsent()?'checked':''}> 익명 게임기록 제공을 위한 기기 내 기록에 동의합니다 (선택).</label><details class="consent-details"><summary>기록 범위·보관 안내</summary><small>제작자 김가현의 게임 밸런스 분석용: 무작위 실행 ID·월별 선택·가상 파라미터·엔딩. 실제 이름·연락처는 제외합니다. 일반 플레이어의 기록은 직접 내보내기 전까지 이 기기에만 남습니다. 제공된 서버 기록은 90일 보관하며, 거부해도 플레이할 수 있습니다.</small></details></div><button class="primary" type="submit">입학면접 후보 3명 보기 →</button></form><p class="small-note">매달 면담과 주별 계획으로 함께 자랍니다.</p></section>`;
}
function admissionInterview(){return renderAdmissionInterview({candidates:admissionCandidates(intakeDraft.intakeSeed,intakeOptions(intakeDraft)),profile:intakeDraft.profile,professorName:intakeDraft.professorName,selected:intakeDraft.selected,locale:lang});}
function admissionShare(){if(!validAdmissionRecord(s.admission))return '';return `<section class="admission-share"><h3>이 학생의 공유 코드</h3><label for="admission-code">입학면접에서 같은 후보를 만나는 코드</label><input id="admission-code" readonly value="${admissionCode(s.admission.intakeSeed,s.admission.candidateIndex)}"><button class="secondary" type="button" data-ui="copy-admission">공유 코드 복사</button><p class="small-note">새 게임의 입학면접 전에 입력합니다. 연구 분야와 난도는 새로 정하므로 이후 이야기는 달라질 수 있습니다.</p></section>`;}
function updateProfileSetup(){const d=getDiscipline($('#field-id').value),lab=$('#lab-mode'),before=lab.value;lab.innerHTML=d.labModes.map(m=>`<option value="${m}">${m==='dry'?'Dry lab · 이론·계산':'Wet lab · 실험'}</option>`).join('');if(d.labModes.includes(before))lab.value=before;lab.disabled=false;const institution=$('select[name="institution"]').value;$('#profile-hint').textContent=INSTITUTION_RULES[institution].hint;}

const choice=(value,title,body='',disabled=false)=>`<button class="choice" data-ui="decide" data-choice="${value}" ${disabled?'disabled':''}><strong>${title}</strong>${body?`<span>${body}</span>`:''}</button>`;
function pending(){const p=s.pending;if(!p)return '';let heading='',body='',buttons='';
if(p.kind==='rest-request'){heading=t('이번 달은 조금 쉬고 싶어요.','I would like some rest this month.');body=t(`${restReasonText(p.reason)} 학생이 ${p.weeks}주 정도 회복 시간을 요청했습니다. 이번 달 일정을 시작하기 전에 함께 결정합니다. 휴식을 확보하면 연구에 쓰는 시간은 줄지만, 학생은 자신의 요청을 존중받았다고 느낍니다.${p.critical?' 지금은 몸이나 마음이 한계에 이른 상태입니다. 계획을 유지하더라도 수행 중 연구를 멈추고 회복하게 될 수 있습니다.':''}` ,`${restReasonText(p.reason)} Your student asks for about ${p.weeks} weeks of recovery before this month begins. Honoring the request gives less time for research and helps your student feel heard.`);buttons=choice('allow',t('휴식 시간을 확보한다','Protect recovery time'),t('시험·학회 등 고정 일정을 확인하고, 가능한 주에 휴식을 반영합니다.','Review fixed commitments and schedule rest in available weeks.'))+choice('decline',t('이번 달 연구 계획을 유지한다','Keep this month’s research plan'),t('연구를 이어갑니다. 학생의 부담과 스트레스가 커질 수 있습니다.','Continue research. The student’s burden and stress may increase.'));}
if(p.kind==='lab-warning'){heading='학과장 면담 · 연구실 운영 경고';body=labWarningText(p,lang);buttons=choice('review','회복 계획을 함께 세운다',p.reason==='funding'?'선택 운영 지출을 줄이고 지원·입금 일정을 점검합니다.':'낮아진 업무에 크레딧을 다시 배분한 초안을 확인합니다. 직접 조정할 수 있습니다.')+choice('acknowledge','경고를 확인하고 직접 계획한다','현재 업무 배분과 예산을 유지합니다. 경고만 확인해도 위험은 회복되지 않습니다.');}
if(p.kind==='monthly-issue'){const issues={'grant-selected':['연구과제 선정 결과','신청한 연구과제가 선정됐다. 협약 기간과 연구비 집행 범위를 확인하고, 학생의 연구 계획과 일정을 다시 검토한다.'],'grant-rejected':['연구과제 미선정 결과','이번 신청은 선정되지 않았다. 평가 의견이 제공되면 검토하고, 기존 연구비와 교내 공백 지원으로 우선순위를 조정한다. 학생 개인의 능력에 대한 판정으로 받아들이지 않도록 설명한다.'],'presentation-award':['학술대회 우수발표상','연구 결과와 발표 전달력이 좋은 평가를 받아 우수발표상 수상 소식이 도착했다. 학생은 준비한 시간이 인정받았다는 사실에 한시름 놓는다.'],'internal-admission':['학생의 진학 결정','“다른 환경도 생각해 봤지만, 역시 저는 이 자리가 좋습니다. 여기서 다음 연구를 이어 가고 싶어요.” 외부 지원을 권했지만 학생은 내부 진학을 선택했다.']};[heading,body]=issues[p.id];buttons=monthlyIssueOptions(s,p.id).map(o=>choice(o.value,esc(o.label[lang]),esc(o.hint[lang]),o.disabled)).join('');}
if(p.kind==='conference-plan'){const domestic=p.scope==='domestic',away=domestic&&professorAbroad(s),allowed=domesticAttendanceChoices(s),target=p.targetMonth??(domestic&&isFestival()?s.month:s.month+1),when=target===s.month?'이번 달':'다음 달';heading=domestic?`${when} ${monthName(target)} 국내학회 참석 계획`:'다음 달 해외학회 참석 계획';body=domestic?`${when} ${monthName(target)} 셋째 주 학술대회에 누가 참석할지 정한다. 학생은 학부 과정에서는 청강·현장 학습, 대학원에서는 연구 준비도에 맞춰 발표를 준비한다. 참석 경비는 실제 참석 월에 집행한다.`:'다음 달 학회와 연구실 일정을 검토한다. 학생의 발표는 초록 채택이 필요하다. 참석 경비는 실제 참석 월에 집행한다.';if(away)body+=' 해외 연구년 중이라 교수의 국내학회 참석은 불가능합니다. 학생 단독 참석이나 다음 기회를 선택하세요.';const accepted=s.travel?.status==='accepted';buttons=choice('professor','나만 간다',away?'해외 연구년 중 · 국내 참석 불가':domestic?'참석 경비 20만원':'',domestic&&!allowed.includes('professor'))+choice('student','학생만 간다',domestic?'참석 경비 20만원':'',!domestic&&!accepted)+choice('together','같이 간다',away?'해외 연구년 중 · 국내 동반 불가':domestic?'참석 경비 40만원':'',domestic?!allowed.includes('together'):!accepted)+choice('none','다음 기회를 기약한다',domestic?'참석 경비 없음':'');}
if(p.kind==='failure-counsel'){heading='계속 막히는 것 같아요';body='“몇 번을 다시 해도 잘 안 돼요. 제가 이해하고 있는 게 맞는지도 모르겠어요.” 학생이 연속된 어려움에 속상한 마음을 꺼냈다. 수행 기록을 확인하고, 다음 시도의 범위와 필요한 지원을 의논한다.';buttons=choice('support','부담을 낮추고 회복할 시간을 확보한다')+choice('review','막힌 단계와 기초 개념을 함께 점검한다')+choice('independent','학생이 재시도 계획을 정하도록 맡긴다')+choice('strict','기한을 정하고 보완 결과를 요구한다');}
if(p.kind==='conversation-topic'){heading='이번 면담에서 먼저 꺼낼 이야기';body='진행 보고를 마친 뒤 잠시 대화할 시간이 남았다. 학생이 답하기 편한 질문부터 시작하고, 사적인 이야기는 원하는 만큼만 나누도록 한다.';buttons=choice('daily','일상 · 이번 주 생활은 어땠나요?')+choice('academic','학업 · 수업에서 막힌 부분이 있나요?')+choice('research','연구 · 함께 검토할 문제가 있나요?');}
if(p.kind==='story'){const c=CHAPTERS[p.id];heading=c.title;body=c.body;buttons=choice('encourage',c.options[0])+choice('review',c.options[1]);}
if(p.kind==='presentation-recovery'){heading=p.abroad?'해외학회 발표를 돌아보며':'학회 발표를 돌아보며';body='발표 중 설명이 막히고 질문에 답을 정리하기 어려웠다. 이번 경험을 탓하기보다, 다음 발표에 필요한 연습과 지원을 함께 의논한다.';buttons=choice('rehearse','다음 발표를 함께 연습한다')+choice('support','긴장을 풀고 경험을 돌아본다');}
if(p.kind==='academic-exam'){heading=`${p.level==='undergrad'?'학부 수업의 중요한 주간':'대학원 수업'} · ${p.examType}`;body=p.level==='undergrad'?'학생은 수업 시험과 연구실 일정을 함께 챙기고 있다. 학부에서 배울 기초와 충분한 회복 시간을 먼저 확인한다.':`연구와 함께 듣는 대학원 수업에도 시험이 찾아왔다. ${s.route==='masters'&&s.month<48?'학위논문':'퀄과 학위논문'} 준비를 이어 가면서 수업의 배움을 돌아본다.`;buttons=choice('support','시험을 마친 학생을 격려한다')+choice('routine','배운 내용과 다음 연구를 의논한다');}
if(p.kind==='thesis'){const c=THESIS_SCENES[p.step];heading=`${p.level==='masters'?'석사':'박사'} · ${c.title}`;body=c.body;buttons=c.choices.map(([value,label])=>choice(value,label)).join('');}
if(p.kind==='event'){const e=EVENTS.find(e=>e.id===p.id);heading=adaptEventText(e.title[lang],s,lang);body=counselingBody(e,s,lang);buttons=dilemmaOptions(s,e).map((o,i)=>choice(i,esc(adaptEventText(o.label[lang],s,lang)),o.hint?esc(o.hint[lang])+(o.disabled?' · 현재 연구비로는 집행하기 어렵다.':''):'',o.effects?.lab?.funds<0&&s.lab.funds<-o.effects.lab.funds)).join('');}
if(p.kind==='route'){heading=t('학부 졸업, 진학의 갈림길','Graduation. A choice about graduate school.');body=canContinue(s)?t('두 해 동안 연구실에서 함께했다. 학생은 이제 다음 몇 해의 이야기를 꺼낸다.','You have spent two years together in the lab. Your student begins to talk about the years ahead.'):t('학생은 대학원에 남지 않기로 했다. 다른 길을 선택하는 마음을 먼저 듣는다.','Your student has chosen not to stay. Listen to what they want from a different path.');buttons=choice('masters',t('석사 → 박사','Master’s → PhD'),t('석사과정 후, 박사 진학을 다시 의논합니다.','Revisit the PhD decision after a master’s.'),!canContinue(s))+choice('integrated',t('석박사통합','Integrated MS / PhD'),t('6년의 통합과정으로 연구를 이어갑니다.','Continue into a six-year integrated program.'),!canContinue(s))+choice('graduate',t('학사 졸업으로 마무리','Finish with a bachelor’s degree'));}
if(p.kind==='masters'){const requirements=degreeTargets(s.professorProfile?.fieldId,'masters'),ready=mastersEligible(s);heading=t('석사학위, 새 학기의 계획','A master’s degree. Plans for the new semester.');body=t(`석사과정 성과를 확인합니다. ${[requirements.submissions?`논문 제출 ${requirements.submissions}개`:'',requirements.conferences?`학술 발표 ${requirements.conferences}개`:''].filter(Boolean).join(', ')}가 필요합니다. 새 학기의 계획을 함께 의논합니다.`,'The master’s requires one submission and one presentation. Discuss whether to continue, graduate, or take another semester to complete the work.');buttons=choice('continue',t('박사과정으로 진학','Continue to a PhD'),'',!ready||!canContinue(s))+choice('graduate',t('석사 졸업','Graduate with a master’s'),'',!ready)+(!ready&&!s.mastersExtended?choice('extend',t('한 학기 보완','Extend by one semester')):!ready?choice('graduate',t('학위를 마치지 못하고 과정 정리','Leave without completing the degree')):'');}
if(p.kind==='workshop-plan'){heading='방학 연구실 워크숍';body='공동 세미나를 열지, 연구실 안에서 작은 발표회를 할지 결정합니다. 운영비와 교수 준비 시간이 필요합니다.';buttons=choice('host','외부 연구자 초청 워크숍','운영비 120만원 · 교수 에너지 8 · 학술활동·연구실 운영 및 교류',s.lab.funds<12)+choice('small','연구실 내부 발표회','운영비 30만원 · 교수 에너지 3 · 학습·교류',s.lab.funds<3)+choice('skip','이번 방학에는 개최하지 않음','운영비와 준비 시간을 아끼고 기존 계획을 이어갑니다.');}
if(p.kind==='qual'){heading=t('박사 자격시험','The qualifying examination');body=t(`${s.career.qualAttempts?'첫 응시에서 불합격했습니다. 재응시 준비 기간에 전공과목을 최소 2주 수행해야 합니다. ':''}최근 18개월의 전공과목 학습 기록: ${qualificationStudy(s)}주 (응시 준비 기준 6주). 재응시에서도 불합격하면 과정을 이어 갈 수 없습니다. 학생은 그동안의 문헌과 연구 질문을 다시 정리했다. 지금 응시할지, 준비 시간을 더 확보할지 결정한다.`,'Your student has organized the literature and research questions. Decide whether to take the exam now or make room for more preparation.');buttons=choice('exam',t('자격시험에 응시','Take the examination'))+choice('prepare',t('준비 시간을 확보','Make time to prepare'),t('이번 달 공부와 휴식을 중심으로 다시 계획합니다.','Plan this month around study and recovery.'),s.qualPreparations>=2)+choice('graduate',t('과정을 정리하고 다른 길을 의논','Discuss leaving the program'));}
if(p.kind==='external-admission'){heading='다른 학교에서 이어 갈 연구';body=`“교수님, 지금까지의 연구를 바탕으로 ${p.level==='bachelor'?'다른 대학원 석사과정':'다른 학교의 박사과정'}도 알아보고 있어요. 지원 준비와 앞으로의 연구를 의논하고 싶어요.”`;buttons=choice('encourage','진학을 응원한다','외부 지원을 돕되, 최종 진학지는 학생이 선택합니다.')+choice('remain','잔류를 권유한다','이 연구실에서 이어 갈 수 있는 연구와 지원을 제안합니다.');}
if(p.kind==='sabbatical'){heading=t('교수의 연구년','Your sabbatical year');body=t('이번 학년도 연구년이 시작된다. 자리를 비우더라도 면담과 수업, 행정의 연결을 준비해야 한다.','Your sabbatical begins as year five approaches. Being away still requires a plan for meetings, teaching and administration.');buttons=choice('home',t('국내에서 연구 · 지도 유지','Research at home; keep advising'),t('교수의 연구 시간과 일상 지도를 함께 확보합니다.','Protect research time while keeping the daily connection.'))+choice('away',t('해외 방문연구 · 원격 지도','Visit a lab abroad; advise remotely'),t('원격 면담을 챙기지 않으면 학생과의 거리가 벌어질 수 있습니다.','Keep remote meetings going, or distance may grow.'));}
if(p.kind==='service'||p.kind==='service-review'){heading=t(p.kind==='service'?'전문연구요원 선발 준비 상담':'학위 후 복무 계획 점검','Academic planning');body=p.kind==='service'?t(`학생이 ${s.route==='integrated'?'박사과정의 연구 일정':'박사 진학'}과 병역 계획을 함께 묻는다. 지정 자연계 대학원 여부, 선발 일정과 자격은 소속 대학과 병무청에서 확인해야 한다. 상담은 자동 선발이나 병역 해결을 뜻하지 않는다.${doctoralPhase(s)?'':' 군사교육소집 일정은 박사 단계에 들어선 뒤 의논한다.'}`,'Discuss academic plans and next steps.'):t('박사학위 이후 연구 현장과 복무 계획을 함께 점검한다. 2023년 이후 편입자의 학위 취득·후속 복무 규정을 확인하며, 연구실 밖의 계획을 준비한다.','Review plans after the doctorate.');buttons=((doctoralPhase(s)&&s.service.trainingStartMonth===undefined&&s.service.trainingReturnMonth===undefined&&winterTrainingMonth(s)!==null?choice('training','겨울방학 군사교육소집 일정','1~2월 중 3주 · 그 기간 학생 지도와 연구·학습은 중단합니다. 복귀 후 두 달간 짧은 머리로 표시합니다. 실제 일정은 공식 안내를 확인하세요.'):''))+choice('consult',t('소속 대학과 공식 안내를 함께 확인','Review the official guidance together'))+choice('skip',t('현재 병역 계획을 유지','Keep the current plan'));}
if(p.kind==='defense'){heading=canDefend(s)?t('여덟 번째 학년의 끝, 학위수여','The end of year eight. Commencement.'):t('여덟 번째 학년의 끝, 학위 심사','The end of year eight. The defense.');body=canDefend(s)?t('논문과 발표, 자격시험의 기록이 모였다. 이제 학생은 자기 이름으로 연구실 밖에 나선다. 그리고 다시 몇 해가 지나, 메일 한 통이 도착한다.','Papers, presentations and an examination are complete. Your student steps beyond the lab under their own name. A few years later, a letter arrives.'):t('학위요건을 아직 다 채우지 못했다. 8년의 지도 기간이 끝나 학위 심사를 마칠 수 없다.','The degree requirements are not all complete. The game’s eight years end; a person’s next plan does not.');buttons=choice('defend',t(canDefend(s)?'학위수여, 그리고 몇 해 후의 메일':'학위 심사 결과 확인','The defense, then a letter years later'));}
return `<section id="decision" class="decision ${p.kind==='story'||p.kind==='thesis'||p.kind==='qual'?'main-story-scene':''} ${p.kind==='academic-exam'&&p.level==='undergrad'?'important-exam':''}">${p.kind==='lab-warning'?'':'<div class="story-character">'+portrait()+'</div>'}<div class="decision-label">${p.kind==='rest-request'?'학생이 꺼낸 이야기': ['lab-warning','monthly-issue','conference-plan','workshop-plan','failure-counsel','conversation-topic'].includes(p.kind)?'이번 달 이슈':p.kind==='thesis'?'메인스토리 · 학위심사':p.kind==='story'?'메인스토리 · 함께한 시간':p.kind==='qual'?'메인스토리 · 박사 자격시험':p.kind==='academic-exam'&&p.level==='undergrad'?'중요 일정 · 시험기간':p.kind==='event'&&EVENTS.find(e=>e.id===p.id)?.kind==='dilemma'?'이번 달 이슈':p.kind==='event'&&EVENTS.find(e=>e.id===p.id)?.kind==='counseling'?'학생이 꺼낸 이야기':t('연구실에서 생긴 일','A moment in the lab')}</div><h2>${heading}</h2><p>${body}</p>${p.kind==='lab-warning'||p.kind==='monthly-issue'||p.kind==='event'&&EVENTS.find(e=>e.id===p.id)?.kind==='dilemma'?`<p class="issue-context">운영 연구비 ${currency(s.lab.funds)} · 가장 여유가 적은 업무: ${facultyLabel(Object.keys(s.professor).sort((a,b)=>s.professor[a]-s.professor[b])[0])} ${Math.round(Math.min(...Object.values(s.professor)))}</p>`:''}<div class="choices">${buttons}</div>${(p.kind.startsWith('service')||p.id==='military-hidden')&&lang==='ko'?'<aside class="service-warning" role="note"><strong>전문연구요원 일정과 항목은 정확한 자료를 참고하시오.</strong><p>이 이벤트는 게임용 허구입니다. 군사교육소집 기간과 선발·편입·복무 일정, 자격은 병무청 및 소속 대학의 최신 공식 안내를 확인하세요. 머리가 두 달 후 돌아오는 것은 외형 연출이며 훈련 기간이 아닙니다.</p><a href="https://www.mma.go.kr/contents.do?mc=mma0000765" target="_blank" rel="noopener">병무청 전문연구요원 복무 안내 ↗</a></aside>':''}</section>`;}
function monthIssueSummary(){const entries=s.history.filter(h=>h.month===s.month&&['portfolio-selection','grant-selection','presentation-award','failure-support','conference-plan'].includes(h.kind));if(!entries.length)return '';return `<section class="month-issues" aria-label="이번 달 이슈"><h3>이번 달 이슈</h3><ul>${entries.map(h=>`<li>${h.kind==='presentation-award'?'학술대회 우수발표상 수상':h.kind==='failure-support'?'반복된 어려움에 대한 상담':h.kind==='conference-plan'?`${h.scope==='domestic'?'국내':'해외'}학회 참석 계획 확정`:h.awarded?'연구과제 선정':'연구과제 미선정'}</li>`).join('')}</ul></section>`;}
function issueFollowup(){const h=s.history.findLast(h=>h.month===s.month&&typeof h.response==='string'&&h.response);return h?`<aside class="issue-followup" role="status"><strong>선택 이후 · ${esc(name())}</strong><p>${esc(h.response)}</p><a href="#journal">연구실 기록에서 다시 보기 →</a></aside>`:'';}
function lab(){if(!s.started)return welcome();const currentEnding=s.ending?endingMeta({ending:s.ending,endingReason:s.endingReason,labClosure:s.labClosure,statistics:endingStatistics(s),fieldId:s.professorProfile.fieldId,labMode:s.professorProfile.labMode}):null;return `<div class="lab-layout">${sidebar()}<div class="lab-main"><div class="term-heading"><div><p>${phase()} · ${semester(s.month)}</p><h2>${s.ending?t('그 후의 이야기','The story after'):calendar(s.month)}</h2></div><span class="term-count">${s.month} / 96 ${t('개월','months')} · ${esc(difficultySettings(s).label)}</span></div><section id="live-stage" class="live-lab" aria-label="학생의 도트 연구실">${idleLabScene(s)}</section><details class="mobile-student-summary"><summary>${esc(name())} · ${phase()}</summary>${degreeRequirements()}<dl class="student-numbers"><div><dt>연구비 잔액</dt><dd>${currency(s.lab.funds)}</dd></div><div><dt>학생인건비 계상률</dt><dd>${s.lab.budget.salary}%</dd></div><div><dt>학술 지표</dt><dd>h-index ${s.impact?.hIndex??0} · 논문 ${s.career.papers}</dd></div></dl></details>${progress()}${storyObjective()}<div class="student-voice"><div class="voice-character">${portrait()}</div><p>${s.ending?t(s.ending==='gameover'?'함께한 시간을 정리할 때가 왔다.':'한 사람의 다음 이야기가 시작되었다.','Their next story has begun.'):studentTrainingActive(s)?'군사교육소집 중 · 면담과 학생 지도를 잠시 중단합니다.':s.lastReport?.suspended?t('연구비가 다시 마련될 때까지, 해 온 연구를 정리하고 있어요.','While we wait for funding, I am organizing the work we have already done.'):esc(studentLine(s,lang))} <span class="student-speaker">― ${esc(name())}</span></p>${studentObservation(s,lang)?`<small class="student-observation">${esc(studentObservation(s,lang))}</small>`:''}</div>${s.crisis&&!s.ending?`<div class="notice error" role="alert"><strong>${t('다음 계획을 함께 의논할 때입니다.','Do not postpone the next conversation.')}</strong><p>${t('학생이 계획을 이어가기 어려워합니다. 일정을 조정하고 어떤 지원을 원하는지 물어보세요. 과정을 계속할지 결정할 시간도 함께 확보합니다.','Your student is struggling to continue. Without room for rest and conversation, they may leave next month.')}</p></div>`:''}${screenGuideInvite()}${labRiskNotice()}${issueFollowup()}${fundingResultNotice()}${monthIssueSummary()}${s.ending?`<section class="ending-summary"><span>${endingType(s.ending)}</span><h2>${currentEnding.title[lang]}</h2><p>${currentEnding.career[lang]}</p>${endingCause(s)}<p>${currentEnding.time[lang]}</p><button class="primary" data-ui="read-current">${s.ending==='gameover'?'종료 기록 확인':t('도착한 메일 읽기','Read the letter that arrived')} →</button>${s.ending!=='gameover'?'<button class="secondary" data-ui="view-current-cv">연구자 CV 보기</button>':''}<button class="secondary" data-ui="current-statistics">파라미터 보기</button><button class="secondary" data-ui="new">${t('다시 시작','Start again')}</button></section>`:!s.started?welcome():s.pending?pending():`${project()}${grantPanel()}${report()}${schedule()}<div id="suspension-controls">${suspendedControl()}</div>`}</div></div>`;}
function checkpointPanel(){return `<section class="save-points" aria-label="시점별 저장과 불러오기"><div class="section-top"><h2>시점별 저장 · 불러오기</h2><span>월 진행 전후 자동 저장</span></div><p>계획·파라미터·난수 상태를 그대로 복원합니다. 돌아가기 직전 진행은 자동 보관하며, 수집한 후일담은 유지합니다.</p><div class="save-point-tools"><label for="checkpoint-label">저장점 이름<input id="checkpoint-label" maxlength="60" placeholder="예: 자격시험 준비 전"></label><button class="primary" data-ui="save-point" ${!s.started?'disabled':''}>현재 시점 저장</button><button data-ui="export">현재 시점 파일 저장</button><button data-ui="import">파일 불러오기</button><input type="file" id="journal-import-file" accept="application/json,.json" hidden></div><p class="small-note">이 브라우저에 보관됩니다. 다른 기기로 옮기거나 사이트 데이터를 지우기 전에는 저장점 파일을 내려받으세요. 업데이트 이전 시점은 새로 복원할 수 없습니다.</p><div id="checkpoint-list" aria-live="polite">저장점을 불러오는 중입니다.</div></section>`;}
let checkpointRefresh=0;
async function refreshCheckpoints(){const token=++checkpointRefresh;if(!$('#checkpoint-list'))return;try{const rows=await listCheckpoints();if(token!==checkpointRefresh||!$('#checkpoint-list'))return;
 $('#checkpoint-list').innerHTML=rows.length?`<details open><summary>보관한 저장점 ${rows.length}개</summary><ol class="checkpoint-list">${rows.map(r=>`<li><div><strong>${esc(r.name)} · ${calendar(r.month)}</strong><span>${esc(r.label||({auto:'월별 자동 저장',backup:'회귀 직전 자동 보관',manual:'직접 저장'})[r.kind])}${r.ending?' · 지도 종료':''}</span><time>${new Date(r.savedAt).toLocaleString('ko-KR')}</time></div><div><button data-ui="load-point" data-point="${esc(r.id)}">이 시점으로</button><button data-ui="export-point" data-point="${esc(r.id)}">파일 저장</button><button data-ui="delete-point" data-point="${esc(r.id)}">삭제</button></div></li>`).join('')}</ol></details>`:'<p class="empty-state">아직 저장점이 없습니다. 현재 시점을 저장하거나 다음 달 진행을 시작하면 기록됩니다.</p>';
 const ids=new Set(rows.map(r=>r.id));for(const el of document.querySelectorAll('[data-history-month]')){const id=monthlyCheckpointId({...s,month:Number(el.dataset.historyMonth)});el.innerHTML=ids.has(id)?`<button data-ui="load-point" data-point="${esc(id)}">이 달 시작으로 돌아가기</button>`:'';}
 }catch{if($('#checkpoint-list'))$('#checkpoint-list').textContent='저장점 보관소에 접근하지 못했습니다. 파일 저장·불러오기는 사용할 수 있습니다.';}}
async function autoCheckpoint(state){try{await storeCheckpoint(state,{kind:'auto'});}catch{toast('시점별 자동 저장에 실패했습니다. 현재 게임 자동 저장은 별도로 유지됩니다.');}}
async function restorePoint(id){const target=await readCheckpoint(id);modal(`<h2>${esc(target.name)} · ${calendar(target.month)}으로 돌아갈까요?</h2><p>현재 진행은 회귀 직전 저장점으로 보관합니다. 파라미터와 계획을 복원하고 이미 수집한 후일담은 유지합니다.</p><button class="primary" id="confirm-checkpoint">이 시점 불러오기</button>`);$('#confirm-checkpoint').addEventListener('click',async()=>{if(busy)return;busy=true;$('#confirm-checkpoint').disabled=true;try{await storeCheckpoint(s,{kind:'backup'});s=target;s.locale='ko';travelConsent=false;grantApplication={...(s.grantApplication??{role:'pi',years:3})};letter=null;page=0;save();$('#modal').close();location.hash='lab';render();toast('저장한 시점으로 돌아왔습니다.');}catch{toast('현재 진행을 보관하지 못했습니다. 파일로 저장한 뒤 다시 시도해 주세요.');}finally{busy=false;updateCosts();}});}
function journal(){const entries=s.history.filter(x=>['month','event','issue-read','admission-response','route','promotion','qual','sabbatical','submission','paper','conference','recommendation','ending','conference-festival','research-travel','annual-grant','grant-report','grant-report-delay','grant-application','grant-selection','portfolio-selection','portfolio-payment','external-admission','abstract-submission','abstract-decision','abstract-window-closed','advising-conversation','presentation-failure','presentation-support','presentation-award','failure-support','conference-plan','conversation-topic','workshop','military-training','operating-advance','operating-interest','advance-repayment','rest-request-response','rest-warning','lab-warning','lab-warning-response','lab-recovery','lab-suspension','attendance-adjustment','settlement-support','advising-habit','story','academic-exam','thesis'].includes(x.kind)).slice(-180).reverse();return `${scholarProfile()}${checkpointPanel()}<section class="content-row"><h2>${t('연구실 기록','Lab notebook')}</h2><div><p class="intro-note">${t('계획과 수행은 다를 수 있습니다. 면담·프로젝트·학위의 기록을 함께 봅니다.','Plans and actions can differ. Read the record of meetings, projects and degrees.')}</p>${entries.length?`<ol class="journal-list">${entries.map(h=>{let title='',body='';if(h.kind==='attendance-adjustment'){title='해외 연구년 · 국내학회 참석 계획 조정';body=`해외 연구년 중 국내 참석을 ${ATTENDANCE_LABELS[h.from]??'기존 계획'}에서 ${ATTENDANCE_LABELS[h.attendance]??'가능한 계획'}로 조정했다.`;}else if(h.kind==='rest-request-response'){title=h.choice==='allow'?'학생의 휴식 요청을 받아들이다':'학생의 휴식 요청 후 계획 유지';body=h.choice==='allow'?`${h.weeks}주 회복 시간을 확보하기로 했다. ${restReasonText(h.reason)}`:`연구 계획을 유지하기로 했다. 학생의 부담과 스트레스가 커졌다. ${restReasonText(h.reason)}`;}else if(h.kind==='rest-warning'){title='몸과 마음의 한계 · 수행 중 회복';body=`${h.week}주차 · ${restReasonText(h.reason)} 연구를 멈추고 쉬었다.`;}else if(h.kind==='lab-warning-response'){title='학과장 면담 후 운영 계획';body=h.choice==='review'?'업무 배분과 최소 지출 계획을 검토했다.':'경고를 확인하고 직접 계획하기로 했다.';}else if(h.kind==='lab-warning'){title='학과장 면담 · 연구실 운영 경고';body=h.reason==='funding'?(h.mode==='borrowing'?'연속 학과 차입과 미상환액 증가 · 지출과 다음 연구비 입금을 점검했다.':'필수 운영비 부족 · 지출과 연구비 입금 일정을 점검했다.'):'교수 업무 고갈 · 회복을 위한 업무 배분을 의논했다.';}else if(h.kind==='lab-recovery'){title='연구실 운영 위험 해소';body=h.reason==='funding'?'필수 운영비를 다시 확보했다.':'교수 업무 배분을 조정해 위험한 영역을 회복했다.';}else if(h.kind==='lab-suspension'){title='필수 운영비 부족 · 운영 보류';body='이번 달 연구·학습 성과와 급여 지급을 보류하고 다음 지원 일정을 확인했다.';}else if(h.kind==='settlement-support'){title='신임교수 정착지원';body=`필수 지출 부족액 ${currency(h.amount)} 지원`;}else if(h.kind==='military-training'){title='겨울방학 군사교육소집';body='3주 · 학생 지도와 연구·학습 일정 중단';}else if(['operating-advance','operating-interest','advance-repayment'].includes(h.kind)){title=h.kind==='operating-advance'?'학과 자동 차입 · 운영 계속':h.kind==='operating-interest'?'차입에 따른 추가 부담':'연구비 입금으로 차입 상환';body=`${currency(h.amount)} · 미상환액 ${currency(h.debt)}`;}else if(h.kind==='workshop'){title='방학 워크숍';body=({host:'외부 연구자 초청',small:'연구실 내부 발표회',skip:'이번 방학은 기존 일정 유지'})[h.choice]+` · 운영비 ${currency(h.cost)}`;}else if(h.kind==='admission-response'){title='내부 진학에 대한 학생의 답';body=h.declined?'학생은 현재 학위를 마친 뒤 다른 길을 선택하기로 했다.':'학생은 연구실에서 다음 학위를 이어 가기로 했다.';}else if(h.kind==='issue-read'){title=({'grant-selected':'선정 이후의 운영 계획','grant-rejected':'미선정 이후의 연구 계획','presentation-award':'수상 이후의 연구 계획','internal-admission':'다음 학위의 지도 계획'})[h.id]??'이번 달 이슈';body=monthlyIssueOptions(s,h.id).find(o=>o.value===h.choice)?.label[lang]??'합의한 계획을 유지했다.';if(h.response)body+=' '+h.response;}else if(h.kind==='presentation-award'){title='학술대회 우수발표상';body='연구 결과와 발표 전달력이 인정받았다.';}else if(h.kind==='failure-support'){title='반복된 어려움에 대한 상담';body='재시도와 지원의 범위를 의논했다.';}else if(h.kind==='conference-plan'){title='다음 달 학회 계획';body=({none:'다음 기회를 기약함',professor:'교수 단독',student:'학생 단독',together:'동반'})[h.attendance];}else if(h.kind==='conversation-topic'){title='면담 주제';body=({daily:'일상',academic:'학업',research:'연구'})[h.topic];}else if(h.kind==='presentation-failure'){title='학회 발표를 돌아보다';body='발표의 어려움을 기록하고 다음 연습을 준비했다.';}else if(h.kind==='presentation-support'){title='다음 발표를 위한 면담';body=h.choice==='rehearse'?'발표 연습을 함께 했다.':'경험과 긴장을 함께 돌아봤다.';}else if(h.kind==='advising-habit'){title='면담 방식을 돌아볼 때';body=h.habit==='inattention'?'학생이 구체적인 관심과 피드백을 기다린다.':'같은 칭찬보다 어떤 점이 좋았는지 함께 살핀다.';}else if(h.kind==='advising-conversation'){title='학생과 대화·안부 확인';body='학생의 일정과 별도로 면담 시간을 챙겼다.';}else if(h.kind==='story'){title=CHAPTERS[h.id]?.title;body=CHAPTERS[h.id]?.options[h.choice==='encourage'?0:1];}else if(h.kind==='thesis'){title=`${h.level==='masters'?'석사':'박사'} · ${THESIS_SCENES[h.step]?.title}`;body=h.revision?`${h.revision==='minor'?'일부':'주요'} 수정·보완 의견`:h.step==='verdict'?(h.passed?'학위요건을 충족했다.':'학위요건을 아직 충족하지 못했다.'):'심사 기록을 남겼다.';}else if(h.kind==='academic-exam'){title=`${h.examType} · ${h.level==='undergrad'?'학부 수업':'대학원 수업'}`;body=h.prepared?'수업의 배움을 정리했다.':'다음 학기의 학습 계획을 함께 살핀다.';}else if(h.kind==='abstract-submission'){title='해외학회 초록 투고';body=`프로젝트 ${h.projectId}`;}else if(h.kind==='abstract-decision'){title=h.accepted?'해외학회 초록 채택':'해외학회 초록 미채택';body='심사 결과가 도착했다.';}else if(h.kind==='abstract-window-closed'){title='다음 해외학회를 준비하며';body='이번 학회 참석 기간을 마무리했다.';}else if(h.kind==='portfolio-selection'){title=h.awarded?'새 연구과제 선정':'연구과제 미선정';body=`${h.role==='pi'?'책임연구':'공동참여'} · ${h.years}년`;}else if(h.kind==='portfolio-payment'){title='과제 연차 연구비 입금';body=currency(h.amount);}else if(h.kind==='external-admission'){title=h.choice==='encourage'?'외부 진학 지원':'연구실 잔류 상담';body='다음 연구 환경을 함께 의논했다.';}else if(h.kind==='month'){title=(Array.isArray(h.plan)?h.plan:[]).map(activityName).join(' · ');body=h.suspended?t('연구비 부족으로 운영 보류 · 급여·연구 활동 미실행','Operations suspended for lack of funding; stipends and research paused'):t(`${h.plan?.length??4}주 중 ${(Array.isArray(h.results)?h.results:[]).filter(r=>r?.performed).length}주 수행`,`Carried out ${(Array.isArray(h.results)?h.results:[]).filter(r=>r?.performed).length} of ${h.plan?.length??4} weeks`);}else if(h.kind==='event'){const e=EVENTS.find(e=>e.id===h.id);title=adaptEventText(e?.title[lang]??'',s,lang);body=adaptEventText(e?.options[h.choice]?.label[lang]??'',s,lang);if(h.response)body+=' '+h.response;}else if(h.kind==='ending'){title=ENDINGS[h.ending]?.title?.[lang]||'기록';body=h.ending==='gameover'?closureSummary({endingReason:h.reason??s.endingReason,labClosure:h.labClosure??s.labClosure},lang):ENDINGS[h.ending]?.career?.[lang]||'';}else{title=({route:t('대학원 진학','Graduate admission'),promotion:t('박사과정 진학','Entered the PhD program'),qual:t(h.passed?'자격시험 통과':'자격시험 재응시 준비',h.passed?'Qualifying exam passed':'Preparing an exam retake'),sabbatical:t('교수 연구년 시작','Faculty sabbatical began'),submission:t('논문 제출','Manuscript submitted'),paper:t('논문 게재','Paper accepted'),conference:t('학술 발표','Conference presentation'),recommendation:t('추천서 발송','Recommendation sent'),'conference-festival':t('정기 학술대회','Scheduled conference'),'research-travel':t('해외학회','Overseas conference'),'grant-report':'연차보고서 제출','grant-report-delay':'연차보고 지연','grant-application':'후속 과제 신청','grant-selection':h.awarded?'후속 과제 선정':'후속 과제 미선정·교내 공백지원','annual-grant':t('연구비 연례 지원','Annual research funding')}[h.kind]);if(h.kind==='annual-grant')body=currency(h.amount);if(h.kind==='research-travel')body=t(`${h.attendance==='professor'?'교수 단독 참석 · ':''}경비 ${Math.round((h.cost||0)*10)}만원 · 숙박 ${h.rooms||1}개 방`,`Lodging: ${h.rooms||1} room(s)`);}return `<li><time>${calendar(Math.max(0,h.month-(h.kind==='rest-request-response'?0:1)))}</time><div><h3>${esc(title)}</h3>${body?`<p>${esc(body)}</p>`:''}${h.kind==='month'?`<div class="journal-restore" data-history-month="${Math.max(0,h.month-1)}"></div>`:''}</div></li>`;}).join('')}</ol>`:`<div class="empty-state"><h3>${t('아직 첫 장입니다.','The first page is still blank.')}</h3><p>${t('첫 면담 뒤, 함께 보낸 한 달의 기록이 남습니다.','Complete your first month to begin the notebook.')}</p><a class="primary link-button" href="#lab">${t('학생 지도하러 가기','Go to advising')} →</a></div>`}</div></section>`;}
function letters(){const collected=endingCollection(gallery);return `<section class="mail-workspace"><aside class="mail-folders"><strong>메일함</strong><span>보관함 <b>${gallery.length}</b></span><p>학생별 후일담과 연구 기록</p></aside><div class="mail-content"><div class="mail-toolbar"><h2>보관한 후일담</h2><span>${gallery.length}건</span></div>${gallery.length?`<ol class="mail-list">${gallery.map(entry=>`<li><button class="mail-row" data-ui="read-entry" data-entry="${esc(entry.id)}"><span class="mail-sender">${esc(entry.name)}</span><span class="mail-subject"><strong>${endingMeta(entry).title[lang]}</strong><small>${endingMeta(entry).career[lang]}</small></span><time>${entry.date}</time></button>${entry.cv?`<button class="mail-cv" data-ui="record-cv" data-entry="${esc(entry.id)}" aria-label="${esc(entry.name)} CV">CV</button>`:''}</li>`).join('')}</ol>`:'<p class="empty-state">아직 보관한 후일담이 없습니다. 학생과 함께한 기록은 이곳에 남습니다.</p>'}<section class="ending-collection"><h3>주요 후일담 ${collected.count} / ${collected.total}</h3><p>${collected.unlocked?'퇴임식의 회상이 열렸습니다.':'주요 후일담 8종 중 5종을 모으면 퇴임식의 회상이 열립니다.'}</p>${gallery.some(x=>x.ending==='youtuber')?'<p class="small-note">영상 크리에이터 특수 후일담은 퇴임식 해금 조건에 포함하지 않습니다.</p>':''}${collected.unlocked?'<button class="secondary" data-ui="retirement">퇴임식 회상 보기 →</button>':''}<details><summary>후일담 목록과 단서</summary><div class="letter-grid">${Object.entries(ENDINGS).map(([id,e])=>{const entry=gallery.find(x=>x.ending===id);return `<button class="letter-card ${entry?'unlocked':'locked'}" data-ui="read" data-ending="${id}" ${entry?'':'disabled'}><span>${entry?'✉':'—'}</span><strong>${entry?endingMeta(entry).title[lang]:'아직 읽지 않은 후일담'}</strong><small>${id==='resident_researcher'&&!entry?'함께 일하는 자리도 있을까요?':e.career[lang]}</small></button>`;}).join('')}</div></details></section></div></section>`;}
function scholarProfile(){const papers=s.history.filter(h=>h.kind==='paper'),citations=s.impact?.citations??[];return `<section class="scholar-profile"><div class="scholar-identity">${portrait()}<div><h2>${esc(name())}</h2><p>${esc(getDiscipline(s.professorProfile.fieldId).label)} · ${phase()}</p><small>게임 내 연구 기록</small></div></div><dl class="scholar-metrics"><div><dt>피인용</dt><dd>${citations.reduce((a,b)=>a+b,0)}</dd></div><div><dt>h-index</dt><dd>${s.impact?.hIndex??0}</dd></div><div><dt>게재 논문</dt><dd>${s.career.papers}</dd></div></dl><div class="scholar-table"><table><thead><tr><th>연구 성과</th><th>피인용</th><th>연차</th></tr></thead><tbody>${papers.map((h,i)=>`<tr><td><strong>${esc(projectTitle(s,h.projectId,'ko'))}</strong><small>${esc(name())} · ${esc(JOURNALS[h.journal??'standard']?.label??'연구 논문')} · ${publicationMetric(h.journal??'standard',h.impactFactor)}</small></td><td>${citations[i]??0}</td><td>${Math.ceil(h.month/12)}</td></tr>`).join('')||'<tr><td colspan="3">게재 성과가 생기면 연구별 기록을 보여줍니다.</td></tr>'}</tbody></table></div></section>`;}
let retirementPage=0;
function showRetirement(){const scenes=retirementScenes(gallery);if(!scenes.length)return;retirementPage=Math.min(retirementPage,scenes.length-1);modal(`<div class="visual-novel"><div class="vn-scene"><div class="vn-window"></div><div class="vn-desk"><span class="vn-screen">퇴임식 · 함께한 시간</span></div></div><div class="vn-text"><h2>각자의 자리에서, 다시 만나다</h2><div class="letter-paper"><p>${esc(scenes[retirementPage])}</p></div><div class="letter-pagination"><button data-ui="retire-prev" ${retirementPage===0?'disabled':''}>← 이전</button><span>${retirementPage+1} / ${scenes.length}</span><button data-ui="${retirementPage===scenes.length-1?'close':'retire-next'}">${retirementPage===scenes.length-1?'기록 보관':'다음 →'}</button></div></div></div>`);$('#modal').classList.add('vn-modal');}
const source=(label,url)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
function brandLink(extraClass=''){return `<a class="brand ${extraClass}" href="#home"><img src="./assets/lab-mark.svg" class="lab-brand-mark" alt="Professor Maker 연구실 로고"><span class="brand-name" aria-label="Professor Maker"><span class="brand-initial-p">P</span>rofessor <span class="brand-initial-m">M</span>aker</span></a>`;}
function portal(){return `<section class="portal-hero"><div class="portal-intro"><h1 class="portal-logo">${brandLink('portal-brand')}</h1><p class="portal-eyebrow">교수 업무 포털 · PROFESSOR MAKER</p><p><strong>연구실 경영 &amp; 육성 시뮬레이션</strong>입니다. 당신은 대학의 교수로서 학생지도, 연구, 행정을 수행하며 차세대 연구자를 양성합니다. 학생의 배움과 연구, 연구실의 운영을 함께 돌봅니다.</p><span class="portal-fiction">이 작품에서 등장한 모든 이름, 인물, 사건들은 허구입니다. 실존하는 인물, 장소, 건물, 제품과는 일절 관련이 없습니다.</span></div><section class="portal-login" aria-label="가상 교수자 업무 포털"><p class="portal-login-code">FACULTY SERVICES · PM</p><h2>교수자 업무 포털</h2><p>학생지도 · 연구 · 대학행정</p><div class="portal-account"><span>접속 유형</span><strong>교수자</strong></div><a class="primary" href="#lab">${s.started?'학생지도 이어하기':'학생지도 시작하기'} →</a><small>게임용 가상 포털 · 계정과 비밀번호 없이 시작합니다.</small></section></section><div class="portal-cards"><article><span>01 · 학생 지도</span><h2>한 명의 학생, 여덟 번의 봄</h2><p>학부연구생의 첫 시행착오부터 대학원의 연구까지. 대사와 수행 보고를 읽으며 주별 계획을 함께 고칩니다.</p></article><article><span>02 · 연구실 운영</span><h2>연구만큼 중요한 살림</h2><p>연구비와 학생인건비, 환경과 교수 업무를 조절합니다. 한쪽으로 기울면 다른 곳에서도 신호가 옵니다.</p></article><article><span>03 · 그 후의 이야기</span><h2>각자의 길에서 도착한 메일</h2><p>졸업과 진학, 다양한 진로의 후일담을 만납니다. 함께 쌓은 성과와 추억은 학생별 CV로 남습니다.</p></article></div>`;}
let labSizeObserver;
function syncLabScrollOffset(){
 const lab=$('#live-stage'),summary=$('.faculty-scroll-summary');
 const pinned=lab&&['sticky','fixed'].includes(getComputedStyle(lab).position);
 const offset=(pinned?lab.getBoundingClientRect().height:0)+(summary?.getBoundingClientRect().height??0)+16;
 document.documentElement.style.setProperty('--lab-scroll-offset',`${Math.ceil(offset)}px`);
}
function observeLabSize(){
 labSizeObserver?.disconnect();syncLabScrollOffset();
 if(typeof ResizeObserver==='function'){labSizeObserver=new ResizeObserver(syncLabScrollOffset);for(const el of [$('#live-stage'),$('.faculty-scroll-summary')])if(el)labSizeObserver.observe(el);}
}
let lastRenderedView=null;
function render({focusMain=false}={}){const prepared=screenGuideForRun(screenGuide,s);if(JSON.stringify(prepared)!==JSON.stringify(screenGuide)){screenGuide=prepared;saveScreenGuide();}const v=view(),pageChanged=v!==lastRenderedView;lastRenderedView=v;const titles={home:'교수 업무 포털',lab:t('학생 지도','Advisee management'),journal:t('연구 기록','Progress records'),letters:t('메일함','Alumni correspondence')};document.documentElement.lang=lang;document.body.dataset.locale=lang;document.body.dataset.view=v;document.body.dataset.gameplay=String(s.started&&v==='lab');document.body.dataset.onboarding=String(!s.started&&v==='lab');document.title=`Professor Maker — ${titles[v]}`;$('#app').innerHTML=`<a class="skip-link" href="#main">${t('본문 바로가기','Skip to content')}</a><div class="utility-bar"><div class="container"><span>${s.started?`<span class="utility-user">${esc(s.professorName||'지도교수')}</span> · 교원 접속`:t('Professor Maker · 연구실 경영·육성','Professor Maker · Lab management')}</span><div><button data-ui="guide">${t('플레이 안내','Help')}</button><button data-ui="settings">${t('저장 관리','Save manager')}</button></div></div></div><header class="site-header"><div class="container header-content"><div class="header-brand">${v==='home'?'':brandLink()}<span class="header-system">${t('교수 업무 포털','Faculty portal')}</span></div><nav class="header-nav" aria-label="${t('주 메뉴','Main navigation')}"><a href="#lab" ${v==='lab'?'aria-current="page"':''}>${t('학생 지도','My lab')}</a><a href="#journal" ${v==='journal'?'aria-current="page"':''}>${t('연구 기록','Records')}</a><a href="#letters" ${v==='letters'?'aria-current="page"':''}>${t('메일함','Alumni')}</a></nav></div></header><nav class="breadcrumb" aria-label="${t('현재 위치','Breadcrumb')}"><div class="container"><span>${t('홈','Home')}</span><span aria-hidden="true">›</span><strong aria-current="page">${titles[v]}</strong><span class="save-status">${storageOK?t('자동 저장 켜짐','Autosave on'):t('저장 불가 · 파일 내보내기 필요','Storage unavailable · export your save')}</span></div></nav>${s.started&&!s.ending&&v!=='home'?`<div class="faculty-scroll-summary"><strong>${esc(s.professorName||'지도교수')} · ${calendar(s.month)}</strong><span class="professor-current-age" data-professor-age>현재 ${professorAge()}세</span>${Object.entries(s.professor).map(([k,n])=>`<span>${facultyLabel(k)} ${Math.round(n)}</span>`).join('')}<a href="#lab">이번 달 지도계획</a></div>`:''}<main id="main" class="container" tabindex="-1"><div class="page-title ${v==='home'?'home-page-title':''}">${v==='home'?'':`<h1>${titles[v]}</h1>`}<button class="text-button" data-ui="print">${t('인쇄','Print')}</button></div>${v==='home'?portal():v==='lab'?lab():v==='journal'?journal():letters()}</main><footer class="site-footer"><div class="container"><div><strong aria-label="Professor Maker"><span class="brand-initial-p">P</span>rofessor <span class="brand-initial-m">M</span>aker</strong><p>${t('제작자: 김가현 · 한 명의 학생과 함께하는 8년','Concept & original letters by Gahyoun Gim · one student, eight years')}</p><small>${t('이 작품에서 등장한 모든 이름, 인물, 사건들은 허구입니다. 실존하는 인물, 장소, 건물, 제품과는 일절 관련이 없습니다. · © 김가현 · GNU GPL v3','An independent fictional game with an original research lab logo. Any resemblance to real people, places or institutions is coincidental.')}</small><p class="notice-links">진로·진학은 개인의 상황과 희망, 해당 기관의 공식 정보를 살펴 신중하게 결정하시기 바랍니다. 이 게임은 실제 진로 상담이나 제도 안내를 대신하지 않습니다.</p></div><nav class="footer-contact" aria-label="제작자 연락처"><strong>제작자에게 연락하기</strong><a href="https://x.com/dotch_gahyoun" target="_blank" rel="noopener noreferrer">트위터(X) · @dotch_gahyoun ↗</a><a href="mailto:dotchgahyoun@gmail.com">메일 · dotchgahyoun@gmail.com</a><a href="https://github.com/Gahyoun?tab=repositories" target="_blank" rel="noopener noreferrer">김가현의 GitHub 저장소 디렉토리 ↗</a></nav></div></footer>`;if(s.started)$('#app').innerHTML=researchText($('#app').innerHTML,s);observeLabSize();syncScreenGuide();syncOnboardingUpdate();if(v==='journal')void refreshCheckpoints();if(pageChanged||focusMain)enterPage($('#main'),{focus:focusMain});}
function modal(html){const d=$('#modal'),alreadyOpen=d.open,focusedUI=d.contains(document.activeElement)?document.activeElement.dataset.ui:null;d.classList.remove('cv-modal','vn-modal');d.innerHTML=`<button class="modal-close" data-ui="close" aria-label="${t('닫기','Close')}">×</button>${html}`;if(!d.open)d.showModal();if(alreadyOpen&&focusedUI){const target=d.querySelector(`[data-ui="${focusedUI}"]:not(:disabled)`)??d.querySelector('.letter-pagination button:not(:disabled)')??d.querySelector('.modal-close');target?.focus({preventScroll:true});}enterDialog(d,{alreadyOpen,direction:['prev-page','retire-prev'].includes(focusedUI)?-1:1});}
function guide(){modal(`<button type="button" class="text-button update-replay" data-ui="update-open">${RELEASE_NOTES_VERSION} 변경사항 다시 보기 →</button>${s.started&&!s.ending?'<button class="secondary guide-restart" type="button" data-ui="screen-guide-start">실제 연구실 화면 안내 다시 보기 →</button>':''}<h2>${t('교수님의 첫 면담 안내','Your first advising meeting')}</h2><details class="finance-evidence"><summary>분야별 연구비와 지출 안내의 근거</summary><p>분야별 연구비 자료는 전체 전임교원 1인당 집계로, 개인의 과제액이나 선정 확률을 뜻하지 않습니다. 게임에서는 분야 간 차이를 완만하게 조정하고, 연구 방식과 주간 활동에 따라 지출을 나누었습니다.</p><a href="${RESEARCH_FINANCE_SOURCE}" target="_blank" rel="noopener noreferrer">한국연구재단 대학 연구활동 실태조사 · 2024년 활동 ↗</a></details><ol class="guide-list"><li>${t('매달 달력에 따른 4~5주 일정을 논의합니다. 학생 제안과 합의한 계획은 실제 수행과 다를 수 있습니다.','Discuss four or five weekly activities each month. Proposals and agreed plans may differ from what actually happens.')}</li><li>${t('학생이 회복 시간을 요청하면, 한 달을 시작하기 전에 허용할지 결정합니다. 휴식을 허용하면 연구 시간은 줄고 신뢰는 쌓입니다. 계획을 유지하면 부담이 커지며, 몸과 마음이 한계에 이르면 수행 중에도 쉬게 될 수 있습니다.','A request for recovery is discussed before the month begins. Rest reduces research time and builds trust. Continuing increases strain, and critical exhaustion may still stop work.')} </li><li>${t('학생의 능력과 성격은 숨겨져 있습니다. 대사·수행보고·연구성과에서 관찰하세요.','Abilities and personality are hidden. Observe dialogue, reports and research outcomes.')}</li><li>${t('지난달 연구 보고에 맞는 칭찬·지적을 선택하세요. 이유 없는 칭찬이나 근거 없는 지적은 역효과를 냅니다.','Match praise and critique to last month’s evidence. Empty praise or unwarranted criticism can backfire.')}</li><li>${t('학술활동·교육·행정·연구실 운영 중 어느 업무가 0이 되면 학과장 면담으로 경고합니다. 두 달 안에 회복할 계획을 세우세요. 3개월 연속 0이면 운영이 종료됩니다.','A zero faculty responsibility triggers a department meeting. Make a recovery plan within two months. Three consecutive months at zero ends operations.')}</li><li>${t('학생인건비 계상률은 매년 3월에 조정합니다. 출근 방식과 공부·연구의 균형은 매달 의논합니다.','Adjust stipend allocation rates each March. Discuss attendance, study and research plans each month.')}</li><li>${t('4월·10월 셋째 주는 학술대회입니다. 앞의 두 주에 준비하고 남은 주에는 자율 시간을 둘 수도 있습니다.','Week three of April and October is a conference. Prepare beforehand and rest afterward.')}</li><li>${t('2년 뒤 진학, 석사학위와 qual, 3~7년차 중 한 번의 교수 연구년이 찾아옵니다. 학생이 힘들다는 신호를 보내면 다음 달까지 방치하지 마세요.','Admission follows two years, then degree reviews, qual and a sabbatical in years three to seven. Do not ignore warning signs until the next month.')}</li><li>${t('졸업 이후의 진로와 편지는 다양합니다. 대학 교수로 다시 만나는 이야기에는 별도의 조건이 있으며, 각자의 선택과 생활은 서로 다른 후일담으로 남습니다.','Careers and letters vary after graduation. Becoming a fellow professor has its own requirements. Each person’s choices and life have their own epilogue.')}</li></ol><div class="help-foot"><p>${t('모바일: Safari 공유 → 홈 화면에 추가 / Chrome 메뉴 → 앱 설치. 첫 온라인 방문 후 오프라인 플레이가 가능합니다.','Mobile: Safari Share → Add to Home Screen / Chrome menu → Install app. Play offline after the first online visit.')}</p>${installPrompt?'<button class="primary" data-ui="install">'+t('앱 설치','Install app')+'</button>':''}</div>`);}
function settings(){modal(admissionShare()+`<button type="button" class="text-button update-replay" data-ui="update-open">${RELEASE_NOTES_VERSION} 변경사항 다시 보기 →</button><h2>${t('저장 관리','Save manager')}</h2><p>${t('현재 게임과 편지함을 JSON으로 보관하거나 기기 사이에서 옮깁니다. 저장은 이 브라우저에만 남습니다.','Export your game and letters as JSON to keep them or move between devices. Autosaves stay in this browser.')}</p><div class="settings-buttons"><button class="primary" data-ui="export">${t('저장 파일 내보내기','Export save')}</button><button class="secondary" data-ui="import">${t('저장 파일 불러오기','Import save')}</button><input type="file" id="import-file" accept="application/json,.json" hidden><button class="secondary" data-ui="new" ${s.started&&!s.ending||!s.started&&intakeDraft?'disabled':''}>${t('새 학생으로 시작','Start with a new student')}</button></div>${s.started&&!s.ending?'<p class="small-note">현재 학생의 지도가 끝나면 새로운 입학면접을 열 수 있습니다. 진행 중에는 학생을 바꾸지 않습니다.</p>':!s.started&&intakeDraft?'<p class="small-note">이번 입학면접에서는 세 후보 중 한 명을 선택합니다. 후보를 새로 만들지는 않습니다.</p>':''}<label class="consent"><input type="checkbox" id="fast-mode" ${fast?'checked':''}>${t('빠른 진행 · 주간 결과 애니메이션 생략','Fast mode · skip weekly transition animation')}</label><div class="telemetry-choice"><label><input id="analytics-consent" type="checkbox" ${analyticsConsent()?'checked':''}> 익명 게임기록 보관 동의 (선택)</label><small>월별 선택·게임 파라미터·엔딩을 분석용으로 기기에 기록합니다. 일반 플레이어의 기록은 자동 전송되지 않습니다. 내보내기로 제작자에게 제공할지 직접 결정할 수 있습니다. 동의를 해제하면 기기 내 분석 기록이 삭제됩니다.</small><button class="secondary" data-ui="export-analysis">익명 분석 기록 내보내기</button><p class="telemetry-status">${esc(analyticsStatus())}</p></div><p class="small-note">${t('새로 시작해도 발견한 메일은 보관됩니다.','Starting again preserves discovered letters.')}</p>`);}
function openLetter(entry){if(!entry)return;letter=entry;page=0;showLetter();}
function endingMeta(entry){const base=getEndingStory(entry.ending,{statistics:entry.statistics,fieldId:entry.fieldId,field:entry.cv?.field,labMode:entry.labMode,relationship:entry.relationship}),context={fieldId:entry.fieldId,field:entry.cv?.field,labMode:entry.labMode},original={...base,title:{...base.title,ko:adaptResearchText(base.title.ko,context)},career:{...base.career,ko:careerDescription(entry.ending,context,'ko',base.career.ko)}};if(entry.ending==='unrelated'&&entry.relationship==='distant')return {...original,title:{...original.title,ko:'연구실 밖의 길'},time:{...original.time,ko:'졸업 2년 뒤 · 메일 없이 남은 후일담'}};if(entry.ending!=='gameover')return original;if(entry.labClosure){return {...original,title:{...original.title,ko:'지속할 수 없었던 연구실'},career:{...original.career,ko:entry.labClosure.reason==='funding'?(entry.labClosure.mode==='borrowing'?'연속 차입과 미상환 부담으로 운영 종료':'필수 연구비 고갈로 운영 종료'):'교수 업무 미회복으로 운영 종료'}};}const description=({graduation_requirements:['졸업 준비 미완료','학위요건 미충족'],time_limit:['마지막 학기의 끝','8년 내 학위 미완료'],qual_failure:['다음 길을 의논하다','자격시험 미통과']})[entry.endingReason];return description?{...original,title:{...original.title,ko:description[0]},career:{...original.career,ko:description[1]},time:{...original.time,ko:'지도 기간의 마지막 기록'}}:original;}
function endingPages(entry=letter){return getEndingPages(entry.ending,lang,entry.relationship,entry.name,entry.endingReason,entry.memories||[],{statistics:entry.statistics,recommendation:entry.evidence?.recommendation,fieldId:entry.fieldId,field:entry.cv?.field,labMode:entry.labMode,labClosure:entry.labClosure,passageIds:entry.passageIds}).map(text=>researchText(text,{professorProfile:{labMode:entry.labMode??s.professorProfile.labMode}}));}
function credits(){return `<section class="ending-credits"><p>PROFESSOR MAKER</p><h3>제작자: 김가현</h3><nav class="footer-contact" aria-label="제작자 연락처"><strong>제작자에게 연락하기</strong><a href="https://x.com/dotch_gahyoun" target="_blank" rel="noopener noreferrer">트위터(X) · @dotch_gahyoun ↗</a><a href="mailto:dotchgahyoun@gmail.com">메일 · dotchgahyoun@gmail.com</a><a href="https://github.com/Gahyoun?tab=repositories" target="_blank" rel="noopener noreferrer">GitHub 저장소 디렉토리 ↗</a></nav><p>함께한 시간은 각자의 다음 이야기로 이어집니다.</p></section>`;}
function showLetter(){const e=endingMeta(letter),pages=endingPages(),body=pages[page],isMail=/교수님께\.|Dear Professor,|메일은 이렇게 이어졌다\.|The email continued\./.test(body),last=page===pages.length-1;
 modal(`<div class="letter-reader visual-novel"><div class="vn-scene ${isMail?'vn-mail':'vn-memory'}" aria-label="${isMail?'메일이 도착한 교수의 책상':'연구실을 돌아보는 장면'}"><div class="vn-window"><i></i><i></i></div><div class="vn-desk"><span class="vn-screen">${isMail?'새 메일 1통':'함께한 기록'}</span><span class="vn-cup"></span></div><div class="vn-scene-caption">${e.time[lang]}</div></div><div class="vn-text"><div class="letter-meta">${endingType(letter.ending)}<span>${e.career[lang]}</span></div><h2>${e.title[lang]}</h2>${endingCause(letter)}<p class="letter-time">${isMail?`보낸 사람: ${esc(letter.name)} · 받는 사람: 지도교수`:'지도교수의 회상'}</p><div class="letter-paper" aria-live="polite">${body.split('\n\n').map(p=>`<p>${esc(p).replaceAll('\n','<br>')}</p>`).join('')}</div><div class="letter-pagination"><button class="secondary" data-ui="prev-page" ${page===0?'disabled':''}>← 이전</button><span>${page+1} / ${pages.length}</span>${!last?'<button class="primary" data-ui="next-page">다음 →</button>':letter.ending!=='gameover'?'<button class="primary" data-ui="view-cv">함께한 기록 보기 →</button>':'<button class="primary" data-ui="finish-letter">종료 기록 보관</button>'}</div>${last?`${renderEvidence(letter.evidence)}${credits()}${letter.statistics?'<button class="secondary" data-ui="view-statistics">종료 시점 파라미터 보기</button>':''}`:''}</div></div>`);$('#modal').classList.add('vn-modal');$('#modal').scrollTop=0;}
let activeCV=null;
async function showCV(entry){
  if(!entry||entry.ending==='gameover')return;
  if(!entry.cv&&entry.ending===s.ending&&entry.name===s.name)await archive();
  if(!entry.cv){toast('이전 버전의 메일에는 CV 기록이 없습니다.');return;}
  busy=true;try{const result=await runEngine('cv-render',{model:entry.cv});activeCV=result;activeCV.css=await fetch("./cv.css").then(r=>r.text());modal(`<div class="cv-actions"><button class="secondary" data-ui="download-cv">CV 파일 저장</button><button class="secondary" data-ui="print-cv">인쇄 · PDF 저장</button><button class="primary" data-ui="finish-letter">기록을 서랍에 넣기</button></div>${result.html}`);$('#modal').classList.add('cv-modal');$('#modal').scrollTop=0;}catch(error){toast('CV를 불러오지 못했습니다. 다시 시도해 주세요.');}finally{busy=false;}
}
function downloadCV(){if(!activeCV)return;const documentHTML=`<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; font-src data:; base-uri 'none'; form-action 'none'"><title>${esc(activeCV.model.name)} · 연구자 CV</title><style>${activeCV.css||''}</style><body>${activeCV.html}</body></html>`;const url=URL.createObjectURL(new Blob([documentHTML],{type:'text/html;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='professor-maker-cv.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function newGame(){if(s.started&&!s.ending){toast('현재 학생의 지도가 끝나면 새 입학면접을 열 수 있습니다.');return;}if(!s.started&&intakeDraft){toast('이번 면접의 세 후보 중 한 명을 선택해 주세요.');return;}modal(`<h2>${t('새로운 이야기를 시작할까요?','Begin a new story?')}</h2><p>${t('학생마다 교수 프로필과 연구실을 새로 정합니다. 현재 게임을 바꾸며, 발견한 메일과 CV는 보관됩니다.','Replace the current run. Discovered letters are kept.')}</p><div class="settings-buttons"><button class="secondary" data-ui="export">${t('먼저 내보내기','Export first')}</button><button class="primary" data-ui="confirm-new">${t('교수 프로필 정하고 새 학생 만나기','Begin new game')}</button></div>`);}
function exportSave(state=s){if(!validateSave(state)){toast(t('업무 배분과 예산을 올바르게 조정한 뒤 내보내 주세요.','Complete a valid allocation and budget before exporting.'));return;}const url=URL.createObjectURL(new Blob([JSON.stringify({format:'professor-maker',version:VERSION,state,gallery,seenPassageIds},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='professor-maker-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('저장 파일을 내보냈습니다.','Save exported.'));}
function updateCosts(){const total=Object.values(s.allocation).reduce((a,b)=>a+b,0),cost=estimate();if($('#allocation-total')){$('#allocation-total').textContent=t('합계 ','Total ')+total+' / '+facultyCapacity(s).credits;$('#allocation-total').classList.toggle('danger-text',total>facultyCapacity(s).credits);}if($('#stipend-amount'))$('#stipend-amount').textContent=t('학생인건비 ','Monthly stipend ')+currency(salaryBase()*s.lab.budget.salary/100);if($('#research-budget-details'))$('#research-budget-details').innerHTML=researchBudgetDetails();if($('#expense-amount'))$('#expense-amount').textContent=t('이번 달 예상 지출 ','Estimated expenditure ')+currency(cost);if($('#confirm-cost'))$('#confirm-cost').textContent=currency(cost);if($('#domestic-conference-cost'))$('#domestic-conference-cost').textContent=currency(conferenceCosts(s).domestic);const status=planReadiness(s,grantApplication);if($('#grant-annual-preview'))$('#grant-annual-preview').textContent=`이번 역할의 신규 과제 · 선정 시 연간 예정액 ${currency(applicationGrantAmount(s,grantApplication.role))}`;if($('#confirm-borrowing')){$('#confirm-borrowing').textContent=`부족액 ${currency(status.estimatedBorrowing)} 자동 차입`;$('#confirm-borrowing').classList.toggle('hidden',!status.estimatedBorrowing);}$('#budget-error')?.classList.toggle('hidden',status.ready&&!status.estimatedBorrowing);if($('[data-plan-block]'))$('[data-plan-block]').textContent=planNoticeMessage(status);const button=$('[data-ui=advance]');if(button)button.disabled=busy||!validateSave(s)||!status.ready;if($('#suspension-controls'))$('#suspension-controls').innerHTML=suspendedControl();const suspend=$('[data-ui=suspend]');if(suspend)suspend.disabled=busy||!validateSave(s)||!essentialLabStatus(s).blocked;const recovery=recoveryPlan(s),consent=currentRestConsent();if($('#recovery-plan-status'))$('#recovery-plan-status').textContent=recoveryStatus(recovery);const rest=$('[data-ui=respect-rest]');if(rest){const action=!consent&&recovery.request?'discuss':consent?.choice==='allow'&&recovery.missing.length?'restore':null;rest.disabled=busy||!action;rest.hidden=!action;rest.textContent=action==='restore'?t('합의한 휴식 복원','Restore agreed recovery'):t('휴식 요청 함께 의논','Discuss the rest request');}syncScreenGuide();}
function errorMessage(error){const m=error.message;return m.includes('observation is limited')?'현장에서 배우는 일정은 학회 주간에만 선택할 수 있습니다.':m.includes('accepted abstract')?t('초록이 채택된 뒤 참석할 수 있습니다.','An accepted abstract is required.'):m.includes('Abstract submission')?t('대학원부터 방학 첫 달에 초록을 투고할 수 있습니다.','Submit an abstract at the start of graduate vacation.'):m.includes('salary')||m.includes('Stipend')?t('학생인건비 계상률은 매년 3월에만 조정할 수 있습니다.','Stipend rates can change only in the first academic month.'):m.includes('consent')?t('학생의 숙박 동의를 확인해 주세요.','Confirm the student’s consent for shared accommodation.'):m.includes('gender')||m.includes('room')?t('공동 숙박 조건을 확인해 주세요. 다른 성별 또는 미지정이면 방 2개가 필요합니다.','Check accommodation: different or unspecified genders require two rooms.'):m.includes('limit')?t('책임연구 3개·전체 참여 5개 한도를 확인하세요.','Check the grant participation limit.'):m.includes('fund')||m.includes('Budget')?t('연구비 잔액이 부족합니다. 계획을 조정해 주세요.','Funding is insufficient. Adjust the plan.'):m.includes('workload')||m.includes('eight')?t(`교수 업무칸의 합계를 ${facultyCapacity(s).credits}로 맞춰 주세요.`,`Faculty workload units must add up to ${facultyCapacity(s).credits}.`):m;}
async function advance(suspended=false){if(busy)return;busy=true;let lockedControls=[];updateCosts();try{const previousMonth=s.month;const next=await runEngine(suspended?'suspend':'month',{state:s,plan:s.plan,options:{feedback:s.feedback,allocation:s.allocation,budget:s.lab.budget,policies:s.policies,facultyAction:s.facultyAction,grantApplication,attendance:s.attendance,proposal:proposeSchedule(s),travelConsent}});if(next.month===previousMonth&&next.pending){s=next;save();render();focusNextDecision();return;}await autoCheckpoint(s);if(!suspended&&!fast&&!matchMedia('(prefers-reduced-motion:reduce)').matches){const scene=$('#live-stage');let skip=false;scene.classList.add('is-playing');document.body.classList.add('month-playing');for(const el of document.querySelectorAll('.lab-main>:not(#live-stage),.student-panel,.site-header,.site-footer,.breadcrumb,.page-title,.faculty-scroll-summary,.header-nav,.utility-bar,.skip-link'))el.inert=true;lockedControls=[...document.querySelectorAll('[inert] button,[inert] input,[inert] select,[inert] textarea')].map(el=>[el,el.disabled]);for(const [el] of lockedControls)el.disabled=true;window.scrollTo({top:window.scrollY+scene.getBoundingClientRect().top-($('.faculty-scroll-summary')?.getBoundingClientRect().height??0)-8,behavior:'smooth'});const skipHandler=event=>{if(event.target.closest('[data-skip-weeks]'))skip=true;};scene.addEventListener('click',skipHandler);try{for(let i=0;i<next.lastReport.results.length&&!skip;i++){const week=next.lastReport.results[i];scene.innerHTML=weeklyScene(next,week,i)+(week.advanceWarning?`<aside class="weekly-recovery-warning" role="status"><strong>${t('회복이 먼저 필요한 주입니다.','Recovery comes first this week.')}</strong><p>${restReasonText(week.recoveryCause)} ${t('이번 주 연구를 멈추고 쉽니다.','Research pauses for recovery this week.')}</p></aside>`:'')+'<button class="week-skip" data-skip-weeks>이번 달 연출 건너뛰기 →</button>';enterWeek(scene,{first:i===0,monthLabel:calendar(s.month)});focusPlayback(scene);await new Promise(r=>setTimeout(r,1000));}}finally{scene.removeEventListener('click',skipHandler);scene.classList.remove('is-playing');}}s=next;void recordAnalytics(s);if(!s.pending&&!s.ending)s.allocation=allocateCredits(s.allocation,facultyCapacity(s).credits);if(!s.pending&&!s.ending){s.plan=proposeSchedule(s);s.allocation=allocateCredits(s.allocation,facultyCapacity(s).credits);s.feedback='listen';s.facultyAction='routine';}travelConsent=false;await archive();save();await autoCheckpoint(s);render();const fundingNotice=monthlyFundingNotice(s),fundingResults=fundingNotice.results,awards=fundingResults.filter(r=>r.awarded);if(awards.length)toast(`좋은 소식! ${GRANT_TITLES[awards[0].titleIndex]??'연구과제'} 선정 · 추가 연구비 +${currency(awards.reduce((sum,r)=>sum+r.paid,0))}${fundingNotice.repaid?` · 차입 상환 ${currency(fundingNotice.repaid)}`:''}`);else if(fundingNotice.payments.length)toast(`연차 연구비 입금 +${currency(fundingNotice.gross)}`);else if(fundingResults.length)toast(t('이번 연구과제 신청은 선정되지 않았습니다.','This grant application was not selected.'));else if(s.history.some(h=>h.month===s.month&&h.kind==='presentation-award'))toast('좋은 소식! 학술대회 우수발표상을 받았습니다.');if(s.pending)focusNextDecision();else if(s.ending)openLetter(gallery.find(x=>x.id===(s.creationSeed??s.seed)+'-'+s.month+'-'+s.ending)||gallery.find(x=>x.ending===s.ending&&x.name===s.name));else if(!fundingResults.length&&!fundingNotice.payments.length&&!s.history.some(h=>h.month===s.month&&h.kind==='presentation-award'))toast(t('또 한 달의 기록이 쌓였습니다.','Another month in the notebook.'));}catch(error){toast(errorMessage(error));}finally{busy=false;for(const [el,disabled] of lockedControls)el.disabled=disabled;document.body.classList.remove('month-playing');for(const el of document.querySelectorAll('[inert]'))el.inert=false;$('#transition').hidden=true;updateCosts();}}
document.addEventListener('click',async e=>{if(e.target.closest('.skip-link')){e.preventDefault();if(!busy){$('#main')?.focus({preventScroll:true});$('#main')?.scrollIntoView({behavior:'auto',block:'start'});}return;}const b=e.target.closest('[data-ui],[data-credit],[data-adjust]');if(!b||b.disabled||busy)return;if(b.dataset.credit){toggleCredit(b);return;}if(b.dataset.adjust){adjustControl(b);return;}const ui=b.dataset.ui;if(ui==='copy-admission'){const input=$('#admission-code');try{await navigator.clipboard.writeText(input.value);toast('학생 공유 코드를 복사했습니다.');}catch{input.focus();input.select();toast('선택된 공유 코드를 복사해 주세요.');}return;}if(ui==='update-open'){if(s.started||view()!=='lab'){showReleaseNotice=false;seenReleaseNotes=markReleaseNotesSeen(seenReleaseNotes);try{localStorage.setItem(RELEASE_NOTES_KEY,JSON.stringify(seenReleaseNotes));}catch{}syncOnboardingUpdate();modal(`<section class="release-note-review"><span>이번 업데이트 · ${RELEASE_NOTES_VERSION}</span><h2>${esc(RELEASE_NOTES.title)}</h2><ul>${RELEASE_NOTES.changes.map(text=>`<li>${esc(text)}</li>`).join('')}</ul><button class="primary" type="button" data-ui="close">확인 · 안내 닫기</button></section>`);}else{if($('#modal').open)$('#modal').close();showReleaseNotice=true;syncOnboardingUpdate();$('#update-notice-title')?.setAttribute('tabindex','-1');$('#update-notice-title')?.focus({preventScroll:true});}return;}if(ui==='update-close'){showReleaseNotice=false;seenReleaseNotes=markReleaseNotesSeen(seenReleaseNotes);try{localStorage.setItem(RELEASE_NOTES_KEY,JSON.stringify(seenReleaseNotes));}catch{}syncOnboardingUpdate();$('#start-form h3')?.setAttribute('tabindex','-1');$('#start-form h3')?.focus({preventScroll:true});return;}if(ui.startsWith('screen-guide-')){screenGuide=screenGuideForRun(screenGuide,s);screenGuide=moveScreenGuide(screenGuide,ui.slice('screen-guide-'.length));saveScreenGuide();if($('#modal').open)$('#modal').close();if(view()!=='lab')location.hash='lab';render();if(screenGuide.status!=='active')focusNextDecision();return;}if(ui==='respect-rest'){if(currentRestConsent()?.choice==='allow')s.plan=acceptRecoveryPlan(s);else{const request=studentRestRequest(s);if(!request||currentRestConsent())return;s.pending={kind:'rest-request',weeks:request.weeks,reason:request.reason,critical:Boolean(request.critical)};}save();render();focusNextDecision();return;}if(ui==='review-plan'){const issue=planReadiness(s,grantApplication).blockers[0],target=issue==='workload'||!issue&&labRiskStatus(s).items.some(i=>i.key!=='funding')?$('#faculty-allocation'):$('#lab-budget');if(target?.tagName==='DETAILS')target.open=true;const control=issue==='grant-call'?$('#faculty-action'):issue==='grant-limit'?$('#grant-role'):target?.querySelector('button:not(:disabled),select:not(:disabled)');const section=control?.closest('details');if(section)section.open=true;control?.focus({preventScroll:true});(control||target)?.scrollIntoView({behavior:motionAllowed()?'smooth':'auto',block:'start'});return;}if(ui==='save-point'){try{await storeCheckpoint(s,{label:$('#checkpoint-label')?.value});await refreshCheckpoints();toast('현재 시점을 보관했습니다.');}catch{toast('저장점을 보관하지 못했습니다. 파일 저장을 이용해 주세요.');}return;}if(ui==='load-point'){try{await restorePoint(b.dataset.point);}catch{toast('유효한 저장점을 불러오지 못했습니다.');}return;}if(ui==='export-point'){try{exportSave(await readCheckpoint(b.dataset.point));}catch{toast('저장점을 파일로 내보내지 못했습니다.');}return;}if(ui==='delete-point'){const id=b.dataset.point;modal('<h2>이 저장점을 삭제할까요?</h2><p>현재 진행과 수집한 후일담은 유지합니다.</p><button class="primary" id="confirm-delete-point">이 저장점 삭제</button>');$('#confirm-delete-point').addEventListener('click',async()=>{try{await deleteCheckpoint(id);$('#modal').close();await refreshCheckpoints();}catch{toast('저장점을 삭제하지 못했습니다.');}});return;}if(ui==='retirement'){retirementPage=0;showRetirement();return;}if(ui==='retire-next'){retirementPage++;showRetirement();return;}if(ui==='retire-prev'){retirementPage--;showRetirement();return;}if(ui==='export-analysis'){await exportAnalytics();return;}if(ui==='read-entry'){openLetter(gallery.find(x=>x.id===b.dataset.entry));return;}if(ui==='record-cv'){await showCV(gallery.find(x=>x.id===b.dataset.entry));return;}if(ui==='current-statistics'){modal(renderStatistics(endingStatistics(s))+credits());return;}if(ui==='view-statistics'){const record=letter?.statistics||(letter?null:endingStatistics(s));modal((record?renderStatistics(record):'<p>이전 버전의 기록에는 파라미터가 보관되어 있지 않습니다.</p>')+credits());return;}if(ui==='advance'){await advance();return;}if(ui==='suspend'){await advance(true);return;}if(ui==='language'){lang=lang==='ko'?'en':'ko';s.locale=lang;if(!currentRestConsent())s.plan=proposeSchedule(s);if(!isBreak()&&s.facultyAction.startsWith('abroad'))s.facultyAction='routine';save();render();return;}if(ui==='view-cv'){await showCV(letter);return;}if(ui==='view-current-cv'){await showCV(gallery.find(x=>x.id===(s.creationSeed??s.seed)+'-'+s.month+'-'+s.ending)||gallery.find(x=>x.ending===s.ending&&x.name===s.name));return;}if(ui==='download-cv'){downloadCV();return;}if(ui==='print-cv'){window.print();return;}if(ui==='guide'){guide();return;}if(ui==='settings'){settings();return;}if(ui==='close'){$('#modal').close();return;}if(ui==='print'){window.print();return;}if(ui==='decide'){busy=true;try{const recoveryResponse=s.history.findLast(h=>h.kind==='lab-warning-response');const preserveRecovery=s.pending.kind==='lab-warning'&&b.dataset.choice==='review'||recoveryResponse?.choice==='review'&&recoveryResponse.month===s.month||s.pending.kind==='rest-request'||Boolean(currentRestConsent());const choice=s.pending.kind==='event'?Number(b.dataset.choice):b.dataset.choice;s=await runEngine('decision',{state:s,choice});void recordAnalytics(s);if(!s.pending&&!s.ending&&!preserveRecovery){s.plan=proposeSchedule(s);s.allocation=allocateCredits(s.allocation,facultyCapacity(s).credits);s.feedback='listen';s.facultyAction='routine';}await archive();save();await autoCheckpoint(s);render();if(s.ending)openLetter(gallery.find(x=>x.id===(s.creationSeed??s.seed)+'-'+s.month+'-'+s.ending)||gallery.find(x=>x.ending===s.ending&&x.name===s.name));else focusNextDecision();}catch(error){toast(errorMessage(error));}finally{busy=false;updateCosts();}return;}if(ui==='read-current'){openLetter(gallery.find(x=>x.id===(s.creationSeed??s.seed)+'-'+s.month+'-'+s.ending)||gallery.find(x=>x.ending===s.ending&&x.name===s.name));return;}if(ui==='read'){openLetter(gallery.find(x=>x.ending===b.dataset.ending));return;}if(ui==='next-page'){page++;showLetter();return;}if(ui==='prev-page'){page--;showLetter();return;}if(ui==='finish-letter'){$('#modal').close();location.hash='letters';return;}if(ui==='new'){newGame();return;}if(ui==='confirm-new'){if(s.started&&!s.ending||!s.started&&intakeDraft){toast('현재 학생의 지도 또는 입학면접을 먼저 마쳐 주세요.');return;}busy=true;try{if(s.started)await storeCheckpoint(s,{kind:'backup'});s=freshState();intakeDraft=null;saveIntakeDraft();grantApplication={role:'pi',years:3};letter=null;page=0;save();$('#modal').close();location.hash='lab';}catch{toast('현재 진행을 보관하지 못했습니다. 먼저 파일로 저장해 주세요.');return;}finally{busy=false;}render();window.scrollTo(0,0);return;}if(ui==='export'){exportSave();return;}if(ui==='import'){($('#modal').open?$('#modal #import-file'):$('#journal-import-file'))?.click();return;}if(ui==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null;$('#modal').close();}});
document.addEventListener('submit',e=>{if(!['start-form','admission-form'].includes(e.target.id))return;e.preventDefault();if(busy||s.started)return;const data=new FormData(e.target);
 if(e.target.id==='start-form'){if(intakeDraft){toast('이미 열린 면접의 후보 중 한 명을 선택해 주세요.');return;}const code=String(data.get('admissionShareCode')??'').trim(),shared=code?parseAdmissionCode(code):null;if(code&&!shared){toast('공유 코드 형식을 확인해 주세요.');$('#admission-share-code')?.focus();return;}const name=data.get('professorName')==='custom'?String(data.get('professorSurname')).trim()+' 교수':String(data.get('professorName')).trim().slice(0,40)||'지도교수';const draw=new Uint32Array(1);if(!shared)crypto.getRandomValues(draw);intakeDraft={version:1,intakeSeed:shared?.intakeSeed??draw[0],selected:shared?.candidateIndex??null,profile:{gender:data.get('professorGender'),age:Number(data.get('professorAge')),fieldId:data.get('fieldId'),labMode:data.get('labMode'),institution:data.get('institution'),difficulty:data.get('difficulty')},professorName:name};if(!validIntakeDraft(intakeDraft)){intakeDraft=null;toast('교수 프로필을 확인해 주세요.');return;}saveIntakeDraft();showReleaseNotice=false;seenReleaseNotes=markReleaseNotesSeen(seenReleaseNotes);try{localStorage.setItem(RELEASE_NOTES_KEY,JSON.stringify(seenReleaseNotes));}catch{}render();window.scrollTo(0,0);$('.admission-interview h2')?.setAttribute('tabindex','-1');$('.admission-interview h2')?.focus({preventScroll:true});return;}
 const index=Number(data.get('candidateIndex'));if(!intakeDraft||data.get('candidateIndex')===null||!Number.isInteger(index)||index<0||index>2)return;intakeDraft.selected=index;s=admitCandidate(intakeDraft.intakeSeed,index,intakeOptions(intakeDraft));s.creationSeed=admissionSeed(intakeDraft.intakeSeed,index);s.professorName=intakeDraft.professorName;s.started=true;intakeDraft=null;saveIntakeDraft();screenGuide=screenGuideForRun(screenGuide,s,{newRun:true});saveScreenGuide();s.pending={kind:'conference-plan',scope:'domestic',targetMonth:s.month+1};void recordAnalytics(s);save();void autoCheckpoint(s);render();focusNextDecision();toast(t('첫 면담이 시작되었습니다.','Your first meeting begins.'));
});
document.addEventListener('input',e=>{if(busy)return;const el=e.target;if(el.dataset.allocation){s.allocation[el.dataset.allocation]=Number(el.value);updateCosts();}if(el.dataset.budget){s.lab.budget[el.dataset.budget]=Number(el.value);updateCosts();}});
document.addEventListener('change',async e=>{if(busy)return;const el=e.target;if(el.name==='candidateIndex'){if(!intakeDraft)return;intakeDraft.selected=Number(el.value);saveIntakeDraft();document.querySelectorAll('.candidate-option').forEach(label=>label.classList.toggle('selected',label.querySelector('input').checked));return;}if(el.name==='professorName'){const input=$('#professor-surname'),custom=el.value==='custom';input.classList.toggle('hidden',!custom);input.required=custom;input.disabled=!custom;return;}if(el.id==='analytics-consent'){await setAnalyticsConsent(el.checked);if(s.started)void recordAnalytics(s);return;}if(el.name==='difficulty'){updateDifficultySetup();return;}if(el.name==='fieldId'||el.name==='institution'){updateProfileSetup();return;}if(el.dataset.policy){s.policies??={...DEFAULT_POLICIES};s.policies[el.dataset.policy]=el.value;save();return;}if(el.id==='overseas-attendance'){s.attendance.overseas=el.value;save();renderPlanningControl('#overseas-attendance');return;}if(el.id==='journal-target'||el.id==='conference-target'){if(el.id==='journal-target'&&!s.project.submitted){if(!isAvailableJournal(el.value,s.professorProfile.fieldId))return;s.publication.journal=el.value;s.project.journal=el.value;}else if(el.id==='conference-target')s.publication.conference=el.value;save();renderPlanningControl(`#${el.id}`);return;}if(el.dataset.week!==undefined){s.plan[Number(el.dataset.week)]=el.value;const p=el.closest('.week-plan');p.querySelector('.week-desc').textContent=activityDescription(el.value);updateCosts();save();return;}if(el.name==='feedback'){s.feedback=el.value;$('.feedback-options').querySelectorAll('label').forEach(x=>x.classList.toggle('selected',x.querySelector('input').checked));save();return;}if(el.dataset.allocation||el.dataset.budget){updateCosts();save();return;}if(el.id==='grant-role'||el.id==='grant-years'){grantApplication[el.id==='grant-role'?'role':'years']=el.id==='grant-role'?el.value:Number(el.value);s.grantApplication={...grantApplication};updateCosts();save();return;}if(el.id==='faculty-action'){s.facultyAction=el.value;updateCosts();save();return;}if(el.id==='travel-consent'){travelConsent=el.checked;return;}if(el.id==='fast-mode'){fast=el.checked;save();return;}if(!['import-file','journal-import-file'].includes(el.id))return;const file=el.files[0];el.value='';if(!file)return;if(file.size>4500000){toast(t('저장 파일이 너무 큽니다.','Save file is too large.'));return;}try{const data=JSON.parse(await file.text());if(data.format!=='professor-maker'||![3,VERSION].includes(data.version)||!validateSave(data.state=migrateSave(data.state))||!Array.isArray(data.gallery)||data.gallery.length>40||!data.gallery.every(validLetter)||(Object.hasOwn(data,'seenPassageIds')&&(!Array.isArray(data.seenPassageIds)||!validPassageIds(data.seenPassageIds))))throw new Error('Invalid save');data.gallery=data.gallery.map(migrateLetter);modal(`<h2>${t('저장 파일을 불러올까요?','Import this save?')}</h2><p>${esc(data.state.name)} · ${calendar(data.state.month)}<br>${t('현재 게임을 바꾸고 기존 메일은 함께 보관합니다.','Replace the current run and keep existing discovered letters.')}</p><button class="primary" id="confirm-import">${t('불러오기','Import')}</button>`);$('#confirm-import').addEventListener('click',async()=>{if(busy)return;busy=true;let before=null,changed=false;try{before={state:s,intakeDraft,gallery,seenPassageIds,storageOK,hash:location.hash,values:[...new Set(['pm-save-v4','pm-language','pm-letters-v3',LETTER_PASSAGES_KEY,'pm-fast',ADMISSION_KEY])].map(key=>[key,localStorage.getItem(key)])};if(s.started)await storeCheckpoint(s,{kind:'backup'});changed=true;s=data.state;intakeDraft=null;saveIntakeDraft();s.locale='ko';grantApplication={...(s.grantApplication??{role:'pi',years:3})};travelConsent=false;const migrated=mergeLetterArchives(gallery,data.gallery,seenPassageIds,data.seenPassageIds??[]);gallery=keepGallery(migrated.gallery);seenPassageIds=migrated.seenPassageIds;await archive();save();if(!storageOK)throw new Error('Imported save could not be persisted');$('#modal').close();location.hash='lab';render();await autoCheckpoint(s);toast(t('저장 파일을 불러왔습니다.','Save imported.'));}catch{if(changed&&before){s=before.state;intakeDraft=before.intakeDraft;grantApplication={...(s.grantApplication??{role:'pi',years:3})};gallery=before.gallery;seenPassageIds=before.seenPassageIds;try{for(const [key]of before.values)localStorage.removeItem(key);for(const [key,value]of before.values)if(value!==null)localStorage.setItem(key,value);storageOK=before.storageOK;}catch{storageOK=false;}$('#modal').close();location.hash=before.hash;render();toast(t('불러온 저장을 보관하지 못했습니다. 기존 진행을 유지했습니다.','The imported save could not be stored. Your previous progress was kept.'));}else toast('현재 진행을 보관하지 못했습니다. 먼저 파일로 저장해 주세요.');}finally{busy=false;updateCosts();}});}catch{toast(t('유효한 월간 버전 저장 파일이 아닙니다.','Not a valid monthly-version save.'));}});
